package com.coxstorageplanner;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Every chest plan, in the order the chests were first opened. Stored as a JSON list. */
public final class ChestBook
{
	public static final int MAX_CHESTS = 40;

	private final Map<String, ChestPlan> chests = new LinkedHashMap<>();

	public static ChestBook parse(String json, Gson gson)
	{
		ChestBook book = new ChestBook();
		if (json == null || json.isEmpty())
		{
			return book;
		}
		try
		{
			List<ChestPlan> plans = gson.fromJson(json, new TypeToken<List<ChestPlan>>()
			{
			}.getType());
			if (plans != null)
			{
				for (ChestPlan plan : plans)
				{
					if (plan != null && plan.getKey() != null && book.chests.size() < MAX_CHESTS)
					{
						book.chests.put(plan.getKey(), plan);
					}
				}
			}
		}
		catch (JsonSyntaxException e)
		{
			// a broken config entry: start over rather than crash
		}
		return book;
	}

	public synchronized String encode(Gson gson)
	{
		return gson.toJson(new ArrayList<>(chests.values()));
	}

	public synchronized ChestPlan get(String key)
	{
		return key == null ? null : chests.get(key);
	}

	/** The plan for a key, made with the given name if there wasn't one. Null when full. */
	public synchronized ChestPlan getOrCreate(String key, String name)
	{
		ChestPlan plan = chests.get(key);
		if (plan == null && chests.size() < MAX_CHESTS)
		{
			plan = new ChestPlan(key, name);
			chests.put(key, plan);
		}
		return plan;
	}

	public synchronized boolean remove(String key)
	{
		return chests.remove(key) != null;
	}

	public synchronized List<ChestPlan> all()
	{
		return Collections.unmodifiableList(new ArrayList<>(chests.values()));
	}

	/** Deep copy for a snapshot the Swing thread can read while the plans change. */
	public synchronized ChestBook copy(Gson gson)
	{
		return parse(encode(gson), gson);
	}
}

package com.coxstorageplanner;

/** Which items in the storage light up when a chest's withdrawals are ordered. */
public enum ChestGlow
{
	NEXT_ONLY("Only the next click", 1),
	/** How many is a setting of its own; four unless that says otherwise. */
	NEXT_FOUR("Next few clicks, biggest first", 4),
	GRADIENT("All, first to last", Integer.MAX_VALUE);

	private final String displayName;
	/** How many of the clicks still to make light up, from the next one on. */
	private final int steps;

	ChestGlow(String displayName, int steps)
	{
		this.displayName = displayName;
		this.steps = steps;
	}

	public int getSteps()
	{
		return steps;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.coxstorageplanner;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.geom.AffineTransform;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * Outlines the items a chest plan still wants moved: in the side inventory what goes in,
 * in the storage what comes out, and gear to put on in its own colour before either. With an ordered
 * plan the clicks to make are numbered from the next one: 1, 2, 3, whatever is done already. The next
 * click pulses, and with the next few lit the orbs shrink the further off they are, while the colour
 * says how soon a click comes, green for the next one through yellow and orange to red for the fourth,
 * each step its own colour however many are lit; a setting joins them up with lines, in order.
 * Clicking any of several identical items in the storage takes the first of them and leaves the rest
 * where they are, so only the last of a kind lights: "Xeric's aid, 3" is that one aid clicked three
 * times, with "x3" in the slot's top right corner. A plan held to the slot lights the inventory by slot,
 * so only the items out of place, and never more than the storage has room for.
 */
class ChestItemOverlay extends WidgetItemOverlay
{
	private final Client client;
	private final CoxStoragePlannerPlugin plugin;
	private final CoxStoragePlannerConfig config;
	private final ItemManager itemManager;

	@Inject
	ChestItemOverlay(Client client, CoxStoragePlannerPlugin plugin, CoxStoragePlannerConfig config, ItemManager itemManager)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		showOnInterfaces(InterfaceID.RAIDS_STORAGE_PRIVATE, InterfaceID.RAIDS_STORAGE_SHARED, InterfaceID.RAIDS_STORAGE_SIDE);
	}

	/** Orb diameter of the next withdrawal, which covers the item, and of the nearest and furthest ones after it. */
	private static final int ORB_NEXT = 28;
	private static final int ORB_NEAR = 20;
	private static final int ORB_FAR = 10;

	/** How much of each step has lit up so far this frame, so "Xeric's aid, 2" lights two and not the whole row. */
	private final Map<ChestProgress.Step, Integer> lit = new IdentityHashMap<>();
	/** The withdrawals of a plan held to the slot that an item lit up for so far this frame. */
	private final Set<ChestProgress.Click> taken = Collections.newSetFromMap(new IdentityHashMap<>());
	/** Per item in the open storage: the widget index of the last one of it, and how many of it there are. */
	private final Map<Integer, int[]> twins = new HashMap<>();
	/** The widget those indices are children of. */
	private int twinsParent;
	/** Deposits lit so far this frame, by item name. */
	private final Map<String, Integer> named = new HashMap<>();
	/** Deposits lit so far this frame that take a storage slot. */
	private int slotsLit;
	/** The orbs of the ordered withdrawals drawn this frame, by rank: centre x, centre y, radius; and the colour of the line on from each. */
	private final Map<Integer, int[]> orbs = new TreeMap<>();
	private final Map<Integer, Color> orbColors = new HashMap<>();
	/** The storage slots (by index) handed to renderItemOverlay this frame: the ones scrolled into view. */
	private final Set<Integer> seen = new HashSet<>();

	@Override
	public Dimension render(Graphics2D graphics)
	{
		lit.clear();
		taken.clear();
		named.clear();
		slotsLit = 0;
		twins.clear();
		orbs.clear();
		orbColors.clear();
		seen.clear();
		int group = plugin.getOpenStorage();
		Widget items = group == 0 ? null : client.getWidget(group == InterfaceID.RAIDS_STORAGE_SHARED
			? InterfaceID.RaidsStorageShared.ITEMS : InterfaceID.RaidsStoragePrivate.ITEMS);
		Widget[] slots = items == null ? null : items.getDynamicChildren();
		twinsParent = items == null ? -1 : items.getId();
		for (int i = 0; slots != null && i < slots.length; i++)
		{
			Widget slot = slots[i];
			if (slot == null || slot.getItemId() <= 0 || slot.isHidden())
			{
				continue;
			}
			int[] twin = twins.computeIfAbsent(slot.getItemId(), id -> new int[]{-1, 0});
			twin[0] = Math.max(twin[0], slot.getIndex());
			twin[1] += Math.max(1, slot.getItemQuantity());
		}
		Shape clip = graphics.getClip();
		super.render(graphics);
		graphics.setClip(clip);
		if (slots != null)
		{
			pinHidden(graphics, items, slots);
		}
		if (config.chestGlowPath() && orbs.size() > 1)
		{
			drawPath(graphics);
		}
		return null;
	}

	/**
	 * Joins the orbs up in click order, orb edge to orb edge, each line in the colour of the last click it
	 * leaves: an item clicked three times sends a line a third as strong as a single one, then two thirds, then whole.
	 */
	private void drawPath(Graphics2D graphics)
	{
		Object aa = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		Stroke stroke = graphics.getStroke();
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		int[] from = null;
		Color color = null;
		for (Map.Entry<Integer, int[]> e : orbs.entrySet())
		{
			int[] to = e.getValue();
			if (from != null)
			{
				double dx = to[0] - from[0];
				double dy = to[1] - from[1];
				double length = Math.hypot(dx, dy);
				if (length > from[2] + to[2] + 4)
				{
					double ux = dx / length;
					double uy = dy / length;
					double x1 = from[0] + ux * (from[2] + 1);
					double y1 = from[1] + uy * (from[2] + 1);
					double x2 = to[0] - ux * (to[2] + 1);
					double y2 = to[1] - uy * (to[2] + 1);
					// an arrowhead at the far end, so the line says which way
					Path2D.Double line = new Path2D.Double();
					line.moveTo(x1, y1);
					line.lineTo(x2, y2);
					line.moveTo(x2 - ux * 7 + uy * 4, y2 - uy * 7 - ux * 4);
					line.lineTo(x2, y2);
					line.lineTo(x2 - ux * 7 - uy * 4, y2 - uy * 7 + ux * 4);
					graphics.setStroke(new BasicStroke(4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
					graphics.setColor(new Color(0, 0, 0, Math.min(255, color.getAlpha())));
					graphics.draw(line);
					graphics.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
					graphics.setColor(color);
					graphics.draw(line);
				}
			}
			from = to;
			color = orbColors.get(e.getKey());
		}
		graphics.setStroke(stroke);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa);
	}

	/**
	 * Storage items scrolled out of view are never handed to renderItemOverlay, so their clicks had no orb
	 * and the lines stopped short of them. Each gets its orb pinned to the edge of the storage it's beyond,
	 * with a nick pointing the way, so the line runs on to it and says which way to scroll.
	 */
	private void pinHidden(Graphics2D graphics, Widget items, Widget[] slots)
	{
		ChestProgress progress = plugin.getOpenChest();
		if (!config.chestGlow() || progress == null || !progress.plan.isOrdered())
		{
			return;
		}
		ChestGlow mode = config.chestOrderedGlow();
		int limit = mode == ChestGlow.NEXT_FOUR ? Math.max(2, config.chestGlowCount()) : mode.getSteps();
		Rectangle view = items.getBounds();
		for (Widget slot : slots)
		{
			if (slot == null || slot.getItemId() <= 0 || slot.isHidden() || seen.contains(slot.getIndex()))
			{
				continue;
			}
			int[] twin = twins.get(slot.getItemId());
			if (twin != null && slot.getIndex() != twin[0])
			{
				continue;
			}
			Click click = withdrawal(progress, plugin.itemName(slot.getItemId()), twin != null ? twin[1] : slot.getItemQuantity(), limit);
			if (click == null || orbs.containsKey(click.rank))
			{
				continue;
			}
			Point at = slot.getCanvasLocation();
			int cx = at.getX() + slot.getWidth() / 2;
			int cy = at.getY() + slot.getHeight() / 2;
			if (view.contains(cx, cy))
			{
				continue;
			}
			Look look = look(progress, click, mode, limit);
			Color color = look.color;
			if (click.rank == 0 && config.chestGlowPulse())
			{
				color = fade(color, pulse());
			}
			int size = look.orb;
			int ring = size >= ORB_NEXT ? 2 : 1;
			int half = size / 2 + ring + 1;
			boolean below = cy >= view.y + view.height;
			int x = Math.max(view.x + half, Math.min(view.x + view.width - half, cx));
			int y = below ? view.y + view.height - half : view.y + half;
			// drawOrb centres a big orb in its bounds and sets a small one a pixel up and left of them
			int nudge = size >= ORB_NEXT ? 0 : 1;
			int[] center = drawOrb(graphics, new Rectangle(x - size / 2 + nudge, y - size / 2 + nudge, size, size), size, color, progress.number(click.number));
			// the nick: a point off the orb's outer side, over the storage's edge, pointing the way to scroll
			int base = below ? y + half - 2 : y - half + 2;
			int tip = below ? base + 6 : base - 6;
			Path2D.Double nick = new Path2D.Double();
			nick.moveTo(x - 5, base);
			nick.lineTo(x, tip);
			nick.lineTo(x + 5, base);
			nick.closePath();
			graphics.setColor(new Color(0, 0, 0, Math.min(255, color.getAlpha())));
			graphics.fill(nick);
			graphics.setColor(color);
			graphics.fill(new Path2D.Double(nick, AffineTransform.getTranslateInstance(0, below ? -1 : 1)));
			orbs.put(click.rank, center);
			orbColors.put(click.rank, look.path);
		}
	}

	/** An ordered click's orb: its colour by how soon it comes, its size, and the colour of the line on from it. */
	private static final class Look
	{
		final Color color;
		final int orb;
		final Color path;

		private Look(Color color, int orb, Color path)
		{
			this.color = color;
			this.orb = orb;
			this.path = path;
		}
	}

	private Look look(ChestProgress progress, Click click, ChestGlow mode, int limit)
	{
		int rank = click.rank;
		Color color = config.chestGlowFirstColor();
		// the colour says how soon: the next click's colour on it, the end colour on the last of the
		// clicks shown, each step its own colour, so two left are green and yellow, not green and red
		int span = mode == ChestGlow.NEXT_FOUR ? limit : Math.min(limit, progress.toClick());
		if (span > 1)
		{
			color = blend(color, config.chestGlowLastColor(), step(rank, span));
		}
		// the line on to the next item leaves this one's last click, in that click's colour, and is as
		// faint as that click is far off: "Xeric's aid, 3" sends a third of a line, then two thirds, then whole
		Color last = span > 1 ? blend(config.chestGlowFirstColor(), config.chestGlowLastColor(), step(rank + click.count - 1, span)) : color;
		Color path = fade(last, 1f / Math.max(1, click.count));
		int orb;
		if (mode == ChestGlow.NEXT_FOUR)
		{
			// the next click is big, the ones behind it smaller and fainter the further off
			float far = rank == 0 || limit <= 2 ? 0 : (rank - 1) / (float) (limit - 2);
			orb = rank == 0 ? ORB_NEXT : Math.round(ORB_NEAR - (ORB_NEAR - ORB_FAR) * far);
			color = rank == 0 ? color : fade(color, 0.9f - 0.2f * far);
		}
		else
		{
			orb = ORB_NEAR;
		}
		return new Look(color, orb, path);
	}

	/** A slow breathe between half and full strength. */
	private static float pulse()
	{
		double phase = (System.currentTimeMillis() % 1200) / 1200.0 * 2 * Math.PI;
		return (float) (0.75 + 0.25 * Math.sin(phase));
	}

	/** Whether this item is beyond the step's remaining count; counts it otherwise. */
	private boolean enough(ChestProgress.Step step, WidgetItem widgetItem)
	{
		int already = lit.getOrDefault(step, 0);
		if (already >= step.remaining)
		{
			return true;
		}
		lit.put(step, already + Math.max(1, widgetItem.getQuantity()));
		return false;
	}

	/**
	 * A storage item's place in the withdrawal: its step, its first click's place in the whole list
	 * (for the colour), how many clicks come first (its number, less one), and how many it takes.
	 */
	static final class Click
	{
		final ChestProgress.Step step;
		final int number;
		final int rank;
		final int count;

		private Click(ChestProgress.Step step, int number, int rank, int count)
		{
			this.step = step;
			this.number = number;
			this.rank = rank;
			this.count = count;
		}
	}

	/**
	 * The withdrawal a storage item lights up for this frame, null for none. An item takes the next
	 * clicks that want it, as many as there are of it, so "Xeric's aid, 2" lights two single aids as
	 * two clicks, or one that stands for several as both. With an ordered plan only the next
	 * {@code limit} clicks light, and an item only takes clicks that follow one another.
	 *
	 * @param quantity how many items this one stands for
	 */
	Click withdrawal(ChestProgress progress, String name, int quantity, int limit)
	{
		ChestProgress.Step step = null;
		int number = 0;
		int first = 0;
		int count = 0;
		int left = Math.max(1, quantity);
		if (progress.exact())
		{
			// the clicks that can be made now
			List<ChestProgress.Click> queue = progress.queue();
			for (int rank = 0; rank < queue.size() && rank < limit && left > 0; rank++)
			{
				ChestProgress.Click click = queue.get(rank);
				if (count > 0 && rank != first + count)
				{
					// something else is clicked in between
					break;
				}
				if (taken.contains(click) || !click.step.line.matches(name) || !progress.fullest(click.step.line, name))
				{
					continue;
				}
				taken.add(click);
				left -= click.step.stack ? left : 1;
				if (count++ == 0)
				{
					step = click.step;
					number = click.number;
					first = rank;
				}
			}
			return count == 0 ? null : new Click(step, number, first, count);
		}
		boolean ordered = progress.plan.isOrdered();
		for (ChestProgress.Step next : progress.withdrawSteps(name, limit))
		{
			int already = lit.getOrDefault(next, 0);
			// a stack is one click however many come out of it
			int ahead = next.stack ? 0 : already;
			if (left <= 0 || already >= next.remaining || (ordered && next.rank + ahead >= limit))
			{
				continue;
			}
			if (ordered && count > 0 && next.click + ahead != number + count)
			{
				break;
			}
			int take = next.stack ? left : Math.min(left, next.remaining - already);
			if (ordered && !next.stack)
			{
				take = Math.min(take, limit - next.rank - ahead);
			}
			lit.put(next, already + take);
			left -= take;
			if (count == 0)
			{
				step = next;
				number = next.click + ahead;
				first = next.rank + ahead;
			}
			count += next.stack ? 1 : take;
		}
		return count == 0 ? null : new Click(step, number, first, count);
	}

	/** Whether this is the first item lit for the step, which is the one that carries its "xN". */
	private boolean firstLit(ChestProgress.Step step, WidgetItem widgetItem)
	{
		return lit.getOrDefault(step, 0) == Math.max(1, widgetItem.getQuantity());
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!config.chestGlow())
		{
			return;
		}
		ChestProgress progress = plugin.getOpenChest();
		if (progress == null)
		{
			return;
		}
		String name = plugin.itemName(itemId);
		int group = widgetItem.getWidget().getId() >>> 16;
		if (widgetItem.getWidget().getParentId() == twinsParent)
		{
			seen.add(widgetItem.getWidget().getIndex());
		}
		Color color;
		int order = 0;
		int orb = 0;
		// an ordered withdrawal's place among the clicks lit, and the colour of the line on from it
		int pathRank = -1;
		Color pathColor = null;
		boolean pulse;
		// the "x5" in the slot's corner: how many, or how many clicks
		int times = 0;
		ChestProgress.Step wear = progress.wearStep(name);
		if (wear != null)
		{
			// gear to put on, wherever it is
			if (enough(wear, widgetItem))
			{
				return;
			}
			times = firstLit(wear, widgetItem) ? wear.remaining : 0;
			color = config.chestWearColor();
			pulse = true;
		}
		else if (group == InterfaceID.RAIDS_STORAGE_SIDE && progress.exact())
		{
			// the side inventory's widgets are its slots, in order; if this one isn't, go by the name
			int slot = widgetItem.getWidget().getIndex();
			int already = named.getOrDefault(name, 0);
			if (name.equals(progress.nameAt(slot)) ? !progress.depositsSlot(slot, name) : already >= progress.depositsNamed(name))
			{
				return;
			}
			named.put(name, already + 1);
			times = widgetItem.getQuantity() > 1 ? widgetItem.getQuantity() : 0;
			color = config.chestGlowColor();
			pulse = true;
		}
		else if (group == InterfaceID.RAIDS_STORAGE_SIDE)
		{
			ChestProgress.Step step = progress.depositStep(name);
			if (step == null ? !progress.highlightsDeposit(name) : lit.getOrDefault(step, 0) >= step.remaining)
			{
				return;
			}
			// no more than the storage has slots for
			if (!progress.freeDeposit(name) && slotsLit++ >= progress.free)
			{
				return;
			}
			if (step != null)
			{
				enough(step, widgetItem);
				times = firstLit(step, widgetItem) ? step.remaining : 0;
			}
			color = config.chestGlowColor();
			pulse = true;
		}
		else
		{
			int quantity = widgetItem.getQuantity();
			int[] twin = widgetItem.getWidget().getParentId() == twinsParent ? twins.get(itemId) : null;
			if (twin != null)
			{
				// a click on any of them takes the first and leaves the rest in place: the last one is the one to click
				if (widgetItem.getWidget().getIndex() != twin[0])
				{
					return;
				}
				quantity = twin[1];
			}
			ChestGlow mode = config.chestOrderedGlow();
			int limit = mode == ChestGlow.NEXT_FOUR ? Math.max(2, config.chestGlowCount()) : mode.getSteps();
			boolean ordered = progress.plan.isOrdered();
			Click click = withdrawal(progress, name, quantity, limit);
			if (click == null)
			{
				return;
			}
			times = click.step.stack ? click.step.remaining : click.count;
			int rank = click.rank;
			pulse = !ordered || rank == 0;
			color = ordered ? config.chestGlowFirstColor() : config.chestGlowColor();
			if (ordered)
			{
				// a click keeps its number while the ones before it get made: 1 2 3 4, then 2 3 4 5
				order = progress.number(click.number);
				Look look = look(progress, click, mode, limit);
				color = look.color;
				orb = look.orb;
				pathRank = rank;
				pathColor = look.path;
			}
		}
		if (pulse && config.chestGlowPulse())
		{
			color = fade(color, pulse());
		}
		Rectangle bounds = widgetItem.getCanvasBounds();
		BufferedImage outline = itemManager.getItemOutline(itemId, widgetItem.getQuantity(), color);
		// thicker is the same outline again, shifted a pixel each way; half a pixel is one at half strength;
		// gear to put on gets a pixel more, so it stands out from what's merely to be moved
		double width = Math.max(1, Math.min(4, config.chestGlowWidth())) + (wear != null ? 1 : 0);
		int reach = (int) Math.ceil(width - 1);
		Composite composite = graphics.getComposite();
		for (int dx = -reach; dx <= reach; dx++)
		{
			for (int dy = -reach; dy <= reach; dy++)
			{
				float strength = (float) Math.min(1, width - Math.abs(dx) - Math.abs(dy));
				if (strength > 0)
				{
					graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, strength));
					graphics.drawImage(outline, bounds.x + dx, bounds.y + dy, null);
				}
			}
		}
		graphics.setComposite(composite);
		if (order > 0)
		{
			int[] center = drawOrb(graphics, bounds, orb, color, order);
			if (pathRank >= 0 && !orbs.containsKey(pathRank))
			{
				orbs.put(pathRank, center);
				orbColors.put(pathRank, pathColor);
			}
		}
		if (times > 1 && times != Integer.MAX_VALUE)
		{
			drawCount(graphics, bounds, times, color);
		}
	}

	/** "x5" in the slot's top right corner, small, outlined so it reads over the orb's edge. */
	private static void drawCount(Graphics2D graphics, Rectangle bounds, int count, Color color)
	{
		graphics.setFont(FontManager.getRunescapeSmallFont());
		String text = "x" + count;
		FontMetrics metrics = graphics.getFontMetrics();
		int tx = bounds.x + bounds.width - metrics.stringWidth(text);
		int ty = bounds.y + metrics.getAscent() - 2;
		graphics.setColor(Color.BLACK);
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				graphics.drawString(text, tx + dx, ty + dy);
			}
		}
		graphics.setColor(Color.WHITE);
		graphics.drawString(text, tx, ty);
	}

	/**
	 * A filled circle with the step number in it: the biggest sits over the middle of the item so the
	 * next click can't be missed, the smaller ones in the top left corner.
	 */
	private static int[] drawOrb(Graphics2D graphics, Rectangle bounds, int size, Color color, int order)
	{
		Object aa = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		boolean centered = size >= ORB_NEXT;
		int x = centered ? bounds.x + (bounds.width - size) / 2 : bounds.x - 1;
		int y = centered ? bounds.y + (bounds.height - size) / 2 : bounds.y - 1;
		int ring = centered ? 2 : 1;
		graphics.setColor(new Color(0, 0, 0, Math.min(255, color.getAlpha())));
		graphics.fillOval(x - ring, y - ring, size + 2 * ring, size + 2 * ring);
		graphics.setColor(color);
		graphics.fillOval(x, y, size, size);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa);

		Font font = centered ? FontManager.getRunescapeBoldFont().deriveFont(20f) : FontManager.getRunescapeSmallFont();
		graphics.setFont(font);
		String text = String.valueOf(order);
		FontMetrics metrics = graphics.getFontMetrics();
		int tx = x + (size - metrics.stringWidth(text)) / 2;
		int ty = y + (size + metrics.getAscent() - metrics.getDescent()) / 2;
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, tx + 1, ty + 1);
		graphics.setColor(Color.WHITE);
		graphics.drawString(text, tx, ty);
		return new int[]{x + size / 2, y + size / 2, size / 2 + ring};
	}

	private static Color fade(Color color, float strength)
	{
		return new Color(color.getRed(), color.getGreen(), color.getBlue(), Math.round(color.getAlpha() * strength));
	}

	/**
	 * How far along from the next click's colour to the end colour the click at a rank is, of {@code span}
	 * lit: each step goes half the way that's left, and the last goes all the way, so green to red by four
	 * is green, yellow, orange, red rather than green, lime, amber, red at even spacing.
	 */
	static float step(int rank, int span)
	{
		return rank >= span - 1 ? 1f : 1f - (float) Math.pow(0.5, rank);
	}

	/**
	 * Between two colours the shorter way round the colour wheel, so green to red goes by yellow and
	 * orange rather than through brown; a grey, having no hue, is met in a straight line instead.
	 */
	static Color blend(Color a, Color b, float t)
	{
		int alpha = Math.round(a.getAlpha() + (b.getAlpha() - a.getAlpha()) * t);
		float[] from = Color.RGBtoHSB(a.getRed(), a.getGreen(), a.getBlue(), null);
		float[] to = Color.RGBtoHSB(b.getRed(), b.getGreen(), b.getBlue(), null);
		if (from[1] == 0 || to[1] == 0)
		{
			return new Color(
				Math.round(a.getRed() + (b.getRed() - a.getRed()) * t),
				Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
				Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t), alpha);
		}
		float turn = to[0] - from[0];
		turn -= Math.round(turn);
		Color c = Color.getHSBColor(from[0] + turn * t, from[1] + (to[1] - from[1]) * t, from[2] + (to[2] - from[2]) * t);
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}
}

package com.coxstorageplanner;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * An ordered take-out list as an inventory layout, slot by slot, and the clicks that get the inventory
 * there. A withdrawal lands in the first empty inventory slot and a deposit leaves a hole, so the
 * finished inventory is the list, one slot per click, laid over the slots the plan may use: every slot
 * but the ones holding something neither list touches. Whatever sits in one of those slots and isn't
 * what belongs there goes in, an item of the list in the wrong place included, and comes out again when
 * its slot is the first empty one. The end of the list may sit further down instead: carried in order
 * below where everything before it will land, it's left there, so a rune pouch kept in the last slot stays.
 * Two neighbours of the list the wrong way round are as good as right: clicks 9 and 10 made as 10 and 9
 * leave the two swapped, and nothing is asked back for that.
 *
 * <p>A storage has only so many slots and every item takes one (a stack takes one for the lot), so not
 * everything may fit at once. Then it goes in rounds: put in what fits, take out what the holes ask
 * for, put in the next lot. With one free slot that's a swap at a time. Which deposit comes first is
 * picked by how many withdrawals it opens up. A storage with room for everything never waits: whatever
 * is in the wrong slot goes in before the next withdrawal. While it's tight, an item of the list in the wrong
 * slot isn't put back in, it's dragged to its own ({@link #moves}); and when nothing fits and no hole
 * is where its item can land, up to {@link #BATCH} items come out into whatever slots are empty, to be
 * dragged into place, which frees their storage slots for what they displace.
 */
final class ChestLayout
{
	/** A slot the plan leaves as it is. */
	static final int STAYS = -2;
	/** A slot whose item the take-out list wants somewhere else: back in, to come out in its place. */
	static final int MISPLACED = -1;
	/** How many items wait for a drag at a time, so how many come out of a full storage in one go. */
	static final int BATCH = 4;

	/** One click of the take-out list, which is one slot of the finished inventory. */
	static final class Entry
	{
		final ChestPlan.Line line;
		/** The line's position in the take-out list. */
		final int index;
		/** Whether it's a stack: one click and one slot whatever the count. */
		final boolean stack;
		/** How many the slot should hold: 1, or the stack's count. */
		final int want;

		private Entry(ChestPlan.Line line, int index, boolean stack, int want)
		{
			this.line = line;
			this.index = index;
			this.stack = stack;
			this.want = want;
		}
	}

	/** The finished inventory, in order. Only what's on you or in the storage. */
	final List<Entry> entries = new ArrayList<>();
	/**
	 * Entries before this one belong in the first slots the plan may use, entry k in the k-th. The ones
	 * from here on are carried further down already, in order, and stay where they are.
	 */
	final int head;
	/** Per entry, whether its slot holds it already. */
	final boolean[] placed;
	/** Per entry, how many a stack that's in its slot still lacks. */
	final int[] shortBy;
	/** Per take-out line, whether worn gear covers it. */
	final boolean[] worn;
	/** Per inventory slot: the put-in line that takes it, {@link #MISPLACED}, or {@link #STAYS}. */
	final int[] via;
	/** The inventory slots to empty into the storage, in slot order. */
	final List<Integer> wrong = new ArrayList<>();
	/** Those of {@link #wrong} the storage has room for right now. */
	final Set<Integer> depositNow = new LinkedHashSet<>();
	/** The entries that can be withdrawn right now, in click order. */
	final List<Integer> queue;
	/** Whether it's the turn of the withdrawals: nothing more fits, or a tight storage's round of them isn't finished. */
	final boolean withdrawing;
	/**
	 * With the storage too full for everything: the drags that put an item of the list into the slot it
	 * belongs in, as {from, to}, the next one first; whatever is in that slot swaps places with it.
	 */
	final List<int[]> moves;
	/** Whether it's the turn of the drags. */
	final boolean moving;
	/** Whether {@link #queue} is of the kind that lands in whatever slots are empty, to be dragged into place after. */
	final boolean loose;
	/** Things still have to go in, the storage is full, nothing can come out and no drag helps. */
	final boolean blocked;

	private final Set<String> stackable;
	/** The inventory slots the plan may use, in order. */
	private final int[] layout;
	/** Per entry, the inventory slot it belongs in: its own, or its neighbour's when the two are swapped. */
	private final int[] at;
	/** Per position of {@link #layout} before {@link #head}, the entry that belongs there. */
	private final int[] who;

	/**
	 * @param budgets per put-in line, how many more it takes: MAX_VALUE for all of them
	 * @param names the inventory slot by slot, null for an empty one
	 * @param storage what the storage holds, null if the client hasn't seen it (then anything is assumed to be in it)
	 * @param free storage slots left, negative for unknown
	 * @param wasWithdrawing whether the last look at this storage was in a round of withdrawals
	 * @param wasLoose whether that round was one of withdrawals into whatever slots were empty
	 */
	ChestLayout(List<ChestPlan.Line> takeOut, List<ChestPlan.Line> putIn, int[] budgets, String[] names, int[] quantities,
		Map<String, Integer> worn, Map<String, Integer> storage, int free, Set<String> stackable, boolean wasWithdrawing, boolean wasLoose)
	{
		this.stackable = stackable;
		int n = names.length;
		Map<String, Integer> carried = new HashMap<>();
		for (int s = 0; s < n; s++)
		{
			if (names[s] != null)
			{
				carried.merge(names[s], Math.max(1, quantities[s]), Integer::sum);
			}
		}
		Map<String, Integer> held = storage == null ? Collections.emptyMap() : storage;

		List<Integer> open = new ArrayList<>();
		for (int s = 0; s < n; s++)
		{
			if (names[s] == null || wanted(takeOut, names[s]) || taker(putIn, budgets, takeOut, names[s]) >= 0)
			{
				open.add(s);
			}
		}
		layout = new int[open.size()];
		for (int k = 0; k < layout.length; k++)
		{
			layout[k] = open.get(k);
		}

		Map<String, Integer> wornLeft = new HashMap<>(worn);
		Map<String, Integer> carriedLeft = new HashMap<>(carried);
		Map<String, Integer> storedLeft = storage == null ? null : new HashMap<>(storage);
		this.worn = new boolean[takeOut.size()];
		for (int i = 0; i < takeOut.size(); i++)
		{
			ChestPlan.Line line = takeOut.get(i);
			if (line.wear)
			{
				continue;
			}
			int want = line.count - ChestProgress.take(line, wornLeft, line.count);
			if (want <= 0)
			{
				this.worn[i] = true;
				continue;
			}
			int have = ChestProgress.take(line, carriedLeft, want);
			int there = storedLeft == null ? want - have : ChestProgress.take(line, storedLeft, want - have);
			boolean stack = ChestProgress.stacks(line, stackable, carried) || ChestProgress.stacks(line, stackable, held);
			int slots = stack ? Math.min(1, have + there) : have + there;
			// what the inventory has no slot for is left out, like what's nowhere to be found
			for (int u = 0; u < slots && entries.size() < layout.length; u++)
			{
				entries.add(new Entry(line, i, stack, stack ? have + there : 1));
			}
		}

		// the end of the list, as far back as it's carried in order with room above it for the rest
		at = new int[entries.size()];
		boolean[] kept = new boolean[n];
		int head = entries.size();
		int below = layout.length;
		for (int k = entries.size() - 1; k >= 0; k--)
		{
			int found = -1;
			for (int p = below - 1; p >= k && found < 0; p--)
			{
				String name = names[layout[p]];
				if (name != null && entries.get(k).line.matches(name))
				{
					found = p;
				}
			}
			if (found < 0)
			{
				break;
			}
			at[k] = layout[found];
			kept[layout[found]] = true;
			below = found;
			head = k;
		}
		this.head = head;
		who = new int[head];
		for (int k = 0; k < head; k++)
		{
			who[k] = k;
		}
		// two neighbours the wrong way round: one of them sits in the other's slot, and neither slot holds its own
		for (int k = 0; k + 1 < head; k++)
		{
			String here = names[layout[k]];
			String next = names[layout[k + 1]];
			Entry first = entries.get(k);
			Entry second = entries.get(k + 1);
			if ((here != null && first.line.matches(here)) || (next != null && second.line.matches(next)))
			{
				continue;
			}
			if ((here != null && second.line.matches(here)) || (next != null && first.line.matches(next)))
			{
				who[k] = k + 1;
				who[k + 1] = k;
				k++;
			}
		}
		for (int p = 0; p < head; p++)
		{
			at[who[p]] = layout[p];
		}

		placed = new boolean[entries.size()];
		shortBy = new int[entries.size()];
		for (int k = 0; k < entries.size(); k++)
		{
			Entry entry = entries.get(k);
			int s = at[k];
			if (names[s] != null && entry.line.matches(names[s]))
			{
				placed[k] = true;
				if (entry.stack && quantities[s] < entry.want)
				{
					int more = entry.want - quantities[s];
					shortBy[k] = storage == null ? more : Math.min(more, ChestProgress.count(entry.line, storage));
				}
			}
		}

		via = new int[n];
		Arrays.fill(via, STAYS);
		int[] left = budgets.clone();
		// where the list goes, anything that isn't what belongs there goes in
		for (int k = 0; k < head; k++)
		{
			int s = at[k];
			if (names[s] != null && !placed[k])
			{
				int line = taker(putIn, left, takeOut, names[s]);
				via[s] = line >= 0 ? line : MISPLACED;
				charge(left, line, quantities[s]);
			}
		}
		// past it, only what the put-in list takes
		for (int k = head; k < layout.length; k++)
		{
			int s = layout[k];
			int line = names[s] == null || kept[s] ? -1 : taker(putIn, left, takeOut, names[s]);
			if (line >= 0)
			{
				via[s] = line;
				charge(left, line, quantities[s]);
			}
		}
		// and what an open slot wants that the storage won't have even then
		if (storage != null)
		{
			Map<String, Integer> pool = new HashMap<>(storage);
			for (int s = 0; s < n; s++)
			{
				if (via[s] != STAYS)
				{
					pool.merge(names[s], Math.max(1, quantities[s]), Integer::sum);
				}
			}
			for (int k = 0; k < entries.size(); k++)
			{
				if (placed[k] || ChestProgress.take(entries.get(k).line, pool, 1) > 0)
				{
					continue;
				}
				for (int j = head; j < layout.length; j++)
				{
					int s = layout[j];
					if (names[s] != null && !kept[s] && via[s] == STAYS && entries.get(k).line.matches(names[s]))
					{
						via[s] = MISPLACED;
						break;
					}
				}
			}
		}
		for (int s = 0; s < n; s++)
		{
			if (via[s] != STAYS)
			{
				wrong.add(s);
			}
		}

		List<Integer> clicks = fill(names.clone(), storage == null ? null : new HashMap<>(storage));
		for (int k = 0; k < entries.size(); k++)
		{
			if (shortBy[k] > 0)
			{
				clicks.add(k);
			}
		}
		Collections.sort(clicks);

		boolean tight = storage != null && free >= 0 && newSlots(names, storage) > free;
		Set<Integer> dragged = new LinkedHashSet<>();
		Set<Integer> targets = new LinkedHashSet<>();
		moves = Collections.unmodifiableList(tight ? drags(names, dragged, targets) : new ArrayList<>());
		if (tight)
		{
			fit(names, quantities, storage, free, dragged);
		}
		else
		{
			depositNow.addAll(wrong);
		}
		boolean room = !depositNow.isEmpty();
		// nothing fits and no hole is one its item can land in: out into the empty slots, a few at a time
		// and once that has begun, until BATCH of them wait for their drag
		boolean anywhere = tight && clicks.isEmpty() && (moves.isEmpty() ? !room : wasWithdrawing && wasLoose);
		if (anywhere)
		{
			clicks = loose(names, storage, targets, BATCH - moves.size());
		}
		loose = anywhere && !clicks.isEmpty();
		queue = Collections.unmodifiableList(clicks);

		// only a storage that's tight goes in rounds; with room, what's out of place goes in as soon as it is
		boolean out = wrong.isEmpty() || (tight && wasWithdrawing && !queue.isEmpty());
		moving = !out && !moves.isEmpty();
		withdrawing = out || (!moving && !room);
		blocked = withdrawing && !wrong.isEmpty() && queue.isEmpty();
	}

	/**
	 * The drags that set the list right without the storage: for each slot of the list that lacks its
	 * item, one carried out of place. A swap that sets both slots right comes first.
	 *
	 * @param dragged filled with the slots the drags start from
	 * @param targets filled with the entries the drags are for
	 */
	private List<int[]> drags(String[] names, Set<Integer> dragged, Set<Integer> targets)
	{
		List<int[]> swaps = new ArrayList<>();
		List<int[]> rest = new ArrayList<>();
		for (int k = 0; k < head; k++)
		{
			int to = at[k];
			if (placed[k])
			{
				continue;
			}
			int from = -1;
			boolean swap = false;
			for (int s : wrong)
			{
				if (s == to || dragged.contains(s) || !entries.get(k).line.matches(names[s]))
				{
					continue;
				}
				boolean both = false;
				for (int j = 0; j < head && names[to] != null; j++)
				{
					both |= at[j] == s && entries.get(j).line.matches(names[to]);
				}
				if (from < 0 || (both && !swap))
				{
					from = s;
					swap = both;
				}
			}
			if (from >= 0)
			{
				dragged.add(from);
				targets.add(k);
				(swap ? swaps : rest).add(new int[]{from, to});
			}
		}
		swaps.addAll(rest);
		return swaps;
	}

	/**
	 * Withdrawals that land wherever the first empty slots are, for a storage with no room: the first
	 * entries of the list that aren't in place, aren't carried and are in the storage.
	 */
	private List<Integer> loose(String[] names, Map<String, Integer> storage, Set<Integer> targets, int most)
	{
		int empty = 0;
		for (String name : names)
		{
			empty += name == null ? 1 : 0;
		}
		Map<String, Integer> stored = new HashMap<>(storage);
		List<Integer> picks = new ArrayList<>();
		for (int k = 0; k < head && picks.size() < Math.min(most, empty); k++)
		{
			Entry entry = entries.get(k);
			if (placed[k] || targets.contains(k) || (entry.stack && holds(names, entry.line)))
			{
				continue;
			}
			String name = fullest(entry.line, stored);
			if (name != null)
			{
				stored.merge(name, -(entry.stack ? entry.want : 1), Integer::sum);
				picks.add(k);
			}
		}
		return picks;
	}

	/** Nothing left to put in, and nothing more that can come out. */
	boolean done()
	{
		return wrong.isEmpty() && queue.isEmpty();
	}

	/** How many storage slots putting all of {@link #wrong} in would take. */
	private int newSlots(String[] names, Map<String, Integer> storage)
	{
		Set<String> stacks = new LinkedHashSet<>(storage.keySet());
		int slots = 0;
		for (int s : wrong)
		{
			slots += cost(names[s], stacks);
			stacks.add(names[s]);
		}
		return slots;
	}

	/** Storage slots an item takes: one, or none for a stackable one the storage holds a stack of. */
	private int cost(String name, Set<String> stored)
	{
		return stackable.contains(name) && stored.contains(name) ? 0 : 1;
	}

	/**
	 * Picks the deposits the storage has room for, each time the one that lets the most withdrawals
	 * follow, the lowest slot among equals. So with one free slot the item in the way of something
	 * that's in the storage goes before one whose own replacement is still in the inventory.
	 *
	 * @param dragged slots that get dragged into place instead
	 */
	private void fit(String[] names, int[] quantities, Map<String, Integer> storage, int free, Set<Integer> dragged)
	{
		String[] slots = names.clone();
		Map<String, Integer> stored = new HashMap<>(storage);
		int room = free;
		List<Integer> rest = new ArrayList<>(wrong);
		rest.removeAll(dragged);
		while (!rest.isEmpty())
		{
			int best = -1;
			int bestScore = -1;
			for (int s : rest)
			{
				if (cost(names[s], stored.keySet()) > room)
				{
					continue;
				}
				String[] after = slots.clone();
				after[s] = null;
				Map<String, Integer> has = new HashMap<>(stored);
				has.merge(names[s], Math.max(1, quantities[s]), Integer::sum);
				int score = fill(after, has).size();
				if (score > bestScore)
				{
					best = s;
					bestScore = score;
				}
			}
			if (best < 0)
			{
				break;
			}
			room -= cost(names[best], stored.keySet());
			stored.merge(names[best], Math.max(1, quantities[best]), Integer::sum);
			slots[best] = null;
			rest.remove((Integer) best);
			depositNow.add(best);
		}
	}

	/**
	 * Plays the withdrawals forward: the first empty slot takes its entry if the storage has it, and so
	 * on until a slot's entry isn't there or the list is through. Changes both arguments.
	 *
	 * @param stored null for a storage the client hasn't seen, which is taken to hold everything
	 * @return the entries withdrawn, in order
	 */
	private List<Integer> fill(String[] slots, Map<String, Integer> stored)
	{
		List<Integer> clicks = new ArrayList<>();
		for (int p = 0; p < layout.length; p++)
		{
			if (slots[layout[p]] != null)
			{
				continue;
			}
			if (p >= head)
			{
				break;
			}
			int k = who[p];
			Entry entry = entries.get(k);
			// a stack carried elsewhere would swallow the withdrawal where it sits
			if (entry.stack && holds(slots, entry.line))
			{
				break;
			}
			String name = stored == null ? entry.line.name : fullest(entry.line, stored);
			if (name == null)
			{
				break;
			}
			if (stored != null)
			{
				int rest = stored.get(name) - (entry.stack ? entry.want : 1);
				if (rest > 0)
				{
					stored.put(name, rest);
				}
				else
				{
					stored.remove(name);
				}
			}
			slots[layout[p]] = name;
			clicks.add(k);
		}
		return clicks;
	}

	private static boolean holds(String[] slots, ChestPlan.Line line)
	{
		for (String name : slots)
		{
			if (name != null && line.matches(name))
			{
				return true;
			}
		}
		return false;
	}

	/** The fullest dose of a line's item in the storage, null when it holds none. */
	private static String fullest(ChestPlan.Line line, Map<String, Integer> stored)
	{
		String best = null;
		for (Map.Entry<String, Integer> e : stored.entrySet())
		{
			if (e.getValue() > 0 && line.matches(e.getKey()) && (best == null || ChestProgress.dose(e.getKey()) > ChestProgress.dose(best)))
			{
				best = e.getKey();
			}
		}
		return best;
	}

	/** Whether the take-out list has a line for an item to carry (not to wear). */
	private static boolean wanted(List<ChestPlan.Line> takeOut, String name)
	{
		for (ChestPlan.Line line : takeOut)
		{
			if (!line.wear && line.matches(name))
			{
				return true;
			}
		}
		return false;
	}

	/** The first put-in line that still takes an item, -1 for none. */
	private static int taker(List<ChestPlan.Line> putIn, int[] left, List<ChestPlan.Line> takeOut, String name)
	{
		for (int j = 0; j < putIn.size(); j++)
		{
			ChestPlan.Line line = putIn.get(j);
			if (left[j] > 0 && (line.everything || (line.everythingElse ? !ChestProgress.keeps(takeOut, name) : line.matches(name))))
			{
				return j;
			}
		}
		return -1;
	}

	private static void charge(int[] left, int line, int quantity)
	{
		if (line >= 0 && left[line] != Integer.MAX_VALUE)
		{
			left[line] -= Math.max(1, quantity);
		}
	}
}

package com.coxstorageplanner;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Stroke;
import javax.inject.Inject;
import net.runelite.api.GameObject;
import net.runelite.api.Point;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A mark over the storage unit in the room you're in: a "?" while its chest still has things to wear,
 * put in or take out, a green tick once the inventory says it's all done.
 */
class ChestMarkerOverlay extends Overlay
{
	private static final Color TODO = new Color(255, 220, 90);
	private static final Color DONE = new Color(90, 230, 90);
	private static final int SIZE = 22;
	private static final int HEIGHT = 220;

	private final CoxStoragePlannerPlugin plugin;
	private final CoxStoragePlannerConfig config;

	@Inject
	ChestMarkerOverlay(CoxStoragePlannerPlugin plugin, CoxStoragePlannerConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.chestMarkers())
		{
			return null;
		}
		for (GameObject storage : plugin.getStorageUnits())
		{
			Boolean done = plugin.chestDoneAt(storage);
			if (done == null)
			{
				continue;
			}
			Point point = storage.getCanvasLocation(HEIGHT);
			if (point == null)
			{
				continue;
			}
			Object aa = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			if (done)
			{
				tick(graphics, point.getX(), point.getY());
			}
			else
			{
				question(graphics, point.getX(), point.getY());
			}
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa);
		}
		return null;
	}

	private static void question(Graphics2D graphics, int x, int y)
	{
		Font font = FontManager.getRunescapeBoldFont().deriveFont((float) SIZE);
		graphics.setFont(font);
		FontMetrics metrics = graphics.getFontMetrics();
		int tx = x - metrics.stringWidth("?") / 2;
		int ty = y + metrics.getAscent() / 2;
		graphics.setColor(Color.BLACK);
		graphics.drawString("?", tx + 1, ty + 1);
		graphics.setColor(TODO);
		graphics.drawString("?", tx, ty);
	}

	private static void tick(Graphics2D graphics, int x, int y)
	{
		Stroke stroke = graphics.getStroke();
		int[] xs = {x - SIZE / 2, x - SIZE / 6, x + SIZE / 2};
		int[] ys = {y, y + SIZE / 3, y - SIZE / 3};
		graphics.setStroke(new BasicStroke(5, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		graphics.setColor(Color.BLACK);
		graphics.drawPolyline(xs, ys, 3);
		graphics.setStroke(new BasicStroke(3, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		graphics.setColor(DONE);
		graphics.drawPolyline(xs, ys, 3);
		graphics.setStroke(stroke);
	}
}

package com.coxstorageplanner;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Stroke;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * An arrow from an inventory item to the slot it belongs in, for when the storage is full and the
 * plan can only be put right by dragging. Drawn over the storage's side inventory, or over the
 * inventory itself once the storage is shut.
 */
class ChestMoveOverlay extends Overlay
{
	private static final int HEAD = 9;

	private final Client client;
	private final CoxStoragePlannerPlugin plugin;
	private final CoxStoragePlannerConfig config;

	@Inject
	ChestMoveOverlay(Client client, CoxStoragePlannerPlugin plugin, CoxStoragePlannerConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.chestGlow())
		{
			return null;
		}
		ChestProgress progress = plugin.progressHere();
		if (progress == null || progress.moveFrom() < 0)
		{
			return null;
		}
		Widget items = client.getWidget(plugin.getOpenStorage() != 0 ? InterfaceID.RaidsStorageSide.ITEMS : InterfaceID.Inventory.ITEMS);
		if (items == null || items.isHidden())
		{
			return null;
		}
		Widget from = items.getChild(progress.moveFrom());
		Widget to = items.getChild(progress.moveTo());
		// the widgets are the slots in order; if that one doesn't hold the item, they aren't, so draw nothing
		if (from == null || to == null || from.getItemId() <= 0 || !progress.moveName().equals(plugin.itemName(from.getItemId())))
		{
			return null;
		}
		Rectangle a = from.getBounds();
		Rectangle b = to.getBounds();
		if (a == null || b == null)
		{
			return null;
		}
		Color color = config.chestGlowColor();
		if (config.chestGlowPulse())
		{
			double phase = (System.currentTimeMillis() % 1200) / 1200.0 * 2 * Math.PI;
			color = new Color(color.getRed(), color.getGreen(), color.getBlue(), (int) Math.round(color.getAlpha() * (0.75 + 0.25 * Math.sin(phase))));
		}
		Object aa = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		Stroke stroke = graphics.getStroke();
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setColor(color);
		graphics.setStroke(new BasicStroke(2));
		graphics.drawRoundRect(a.x, a.y, a.width, a.height, 6, 6);
		graphics.drawRoundRect(b.x, b.y, b.width, b.height, 6, 6);

		double x1 = a.getCenterX();
		double y1 = a.getCenterY();
		double x2 = b.getCenterX();
		double y2 = b.getCenterY();
		double angle = Math.atan2(y2 - y1, x2 - x1);
		for (int pass = 0; pass < 2; pass++)
		{
			// black underneath so it reads over any item
			graphics.setColor(pass == 0 ? new Color(0, 0, 0, color.getAlpha()) : color);
			graphics.setStroke(new BasicStroke(pass == 0 ? 5 : 3, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			graphics.drawLine((int) x1, (int) y1, (int) x2, (int) y2);
			graphics.drawLine((int) x2, (int) y2, (int) (x2 - HEAD * Math.cos(angle - 0.5)), (int) (y2 - HEAD * Math.sin(angle - 0.5)));
			graphics.drawLine((int) x2, (int) y2, (int) (x2 - HEAD * Math.cos(angle + 0.5)), (int) (y2 - HEAD * Math.sin(angle + 0.5)));
		}
		graphics.setStroke(stroke);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa);
		return null;
	}
}

package com.coxstorageplanner;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;

/**
 * What to do at one storage unit: things to put in and things to take out, in order.
 * A line is an item name, matched from its start so "Xeric's aid" covers every dose, or a pattern
 * with * and ? like "*chinchompa", with an optional count like "Stinkhorn mushroom, 3".
 * "Ayak | Sang* staff*" takes either, the first by preference; the count, if any, goes at the end and covers the lot.
 * "Venator bow | *chinchompa & Twisted buckler" is the bow, or else the other two: "&" puts several items
 * on a line, each with a count of its own if it wants one.
 * "everything" deposits it all, "everything else" deposits whatever the take-out list doesn't keep.
 * A take-out line starting with "wear" is gear to put on, done once it's worn.
 */
public final class ChestPlan
{
	public static final String EVERYTHING = "everything";
	public static final String EVERYTHING_ELSE = "everything else";
	public static final int MAX_LINES = 40;
	public static final int MAX_LINE = 100;

	/** One line of a list, parsed. */
	public static final class Line
	{
		public final String text;
		public final String name;
		public final int count;
		/** Whether the line says how many with " xN"; a deposit without it means all of them. */
		public final boolean counted;
		public final boolean everything;
		/** A deposit of whatever the take-out list doesn't ask for. */
		public final boolean everythingElse;
		/** A take-out that's done when the item is worn, not carried. */
		public final boolean wear;
		/** The names this line takes, one unless it says "A | B" or "A & B". */
		private final List<String> names;
		/** Compiled forms of the names, null for a plain name; same order as names. */
		private final List<Pattern> patterns;
		/** The choices of an "A | B & C" line, the preferred one first, each as the items it takes; empty for a line of one item. */
		final List<List<Line>> options;
		/** Whether the choices are one item each under one count, so that any mix of them makes up the number. */
		final boolean either;
		/** The line this one is a dose window of ({@link #doses}), null for a line as written. */
		private final Line base;
		/** With a base: the doses this line takes, inclusive. */
		private final int minDose;
		private final int maxDose;

		Line(String text)
		{
			this.base = null;
			this.minDose = 0;
			this.maxDose = Integer.MAX_VALUE;
			this.text = text;
			String lower = text.toLowerCase(Locale.ROOT);
			everything = lower.equals(EVERYTHING) || lower.equals("*") || lower.equals("all");
			everythingElse = lower.equals(EVERYTHING_ELSE) || lower.equals("the rest") || lower.equals("rest");
			boolean wear = false;
			String name = text;
			for (String prefix : new String[]{"wear ", "equip ", "wield "})
			{
				if (lower.startsWith(prefix))
				{
					wear = true;
					name = text.substring(prefix.length()).trim();
					lower = lower.substring(prefix.length()).trim();
					break;
				}
			}
			this.wear = wear;
			String body = name;
			int count = 1;
			boolean counted = false;
			// "Name, 3", or the older "Name x3"
			int comma = lower.lastIndexOf(',');
			int x = lower.lastIndexOf(" x");
			int cut = comma > 0 ? comma : x;
			int numberAt = comma > 0 ? comma + 1 : x + 2;
			if (cut > 0)
			{
				try
				{
					count = Math.max(1, Integer.parseInt(lower.substring(numberAt).trim()));
					name = name.substring(0, cut).trim();
					counted = true;
				}
				catch (NumberFormatException e)
				{
					// the comma or "x" was part of the name
				}
			}
			String prefix = wear ? "wear " : "";
			List<List<Line>> options = new ArrayList<>();
			boolean either = false;
			if (body.contains("|") || body.contains("&"))
			{
				// a count of its own on any item but the last, or an "&": the counts are each item's own
				boolean own = body.contains("&");
				String[] choices = body.split("\\|");
				for (int i = 0; i < choices.length - 1 && !own; i++)
				{
					own = new Line(choices[i].trim()).counted;
				}
				either = !own;
				for (String choice : (own ? body : name).split("\\|"))
				{
					List<Line> items = new ArrayList<>();
					for (String item : choice.split("&"))
					{
						if (!item.trim().isEmpty())
						{
							items.add(new Line(prefix + item.trim() + (counted && !own ? ", " + count : "")));
						}
					}
					if (!items.isEmpty())
					{
						options.add(items);
					}
				}
				if (own)
				{
					name = body;
					count = 1;
					counted = false;
				}
			}
			this.options = options;
			this.either = either;
			this.name = name;
			this.count = count;
			this.counted = counted;
			names = new ArrayList<>();
			patterns = new ArrayList<>();
			for (List<Line> items : options)
			{
				for (Line item : items)
				{
					names.add(item.name);
					patterns.add(item.patterns.get(0));
				}
			}
			if (names.isEmpty())
			{
				names.add(name);
				patterns.add(name.contains("*") || name.contains("?") ? glob(name) : null);
			}
		}

		/**
		 * A copy taking only the potions of this line whose dose is within a window, and nothing without a dose.
		 *
		 * @param text what the copy reads as, null to keep this line's
		 * @param count how many it asks for; whether it says so follows {@code counted}
		 */
		Line doses(int minDose, int maxDose, String text, int count, boolean counted)
		{
			return new Line(this, minDose, maxDose, text == null ? this.text : text, count, counted);
		}

		private Line(Line base, int minDose, int maxDose, String text, int count, boolean counted)
		{
			this.base = base;
			this.minDose = minDose;
			this.maxDose = maxDose;
			this.text = text;
			this.name = base.name;
			this.count = count;
			this.counted = counted;
			this.everything = false;
			this.everythingElse = false;
			this.wear = base.wear;
			this.names = base.names;
			this.patterns = base.patterns;
			this.options = base.options;
			this.either = base.either;
		}

		/** Whether the line is a plain name: no wildcards, no "|", no "&". */
		boolean plain()
		{
			return names.size() == 1 && patterns.get(0) == null;
		}

		private static Pattern glob(String name)
		{
			StringBuilder regex = new StringBuilder();
			for (char c : name.toCharArray())
			{
				regex.append(c == '*' ? ".*" : c == '?' ? "." : Pattern.quote(String.valueOf(c)));
			}
			return Pattern.compile(regex.toString(), Pattern.CASE_INSENSITIVE);
		}

		/** Whether an item with this name is what the line asks for. */
		public boolean matches(String itemName)
		{
			if (everything || everythingElse)
			{
				return true;
			}
			if (itemName == null)
			{
				return false;
			}
			if (base != null)
			{
				int dose = ChestProgress.dose(itemName);
				return dose >= minDose && dose <= maxDose && base.matches(itemName);
			}
			String lower = itemName.toLowerCase(Locale.ROOT);
			for (int i = 0; i < names.size(); i++)
			{
				Pattern pattern = patterns.get(i);
				if (pattern != null ? pattern.matcher(itemName).matches() : lower.startsWith(names.get(i).toLowerCase(Locale.ROOT)))
				{
					return true;
				}
			}
			return false;
		}

		@Override
		public String toString()
		{
			return text;
		}
	}

	private String key;
	private String name;
	private List<String> deposit = new ArrayList<>();
	private List<String> withdraw = new ArrayList<>();
	private boolean ordered;
	/** Whether a potion on the take-out list is swapped for a fuller dose the storage has ({@link ChestProgress#topUp}). */
	private boolean topUp;

	public ChestPlan()
	{
	}

	public ChestPlan(String key, String name)
	{
		this.key = key;
		this.name = name;
	}

	public String getKey()
	{
		return key;
	}

	public String getName()
	{
		return name == null ? "" : name;
	}

	public void setName(String name)
	{
		this.name = name == null ? "" : name.trim();
	}

	public boolean isOrdered()
	{
		return ordered;
	}

	public void setOrdered(boolean ordered)
	{
		this.ordered = ordered;
	}

	public boolean isTopUp()
	{
		return topUp;
	}

	public void setTopUp(boolean topUp)
	{
		this.topUp = topUp;
	}

	public List<String> getDeposit()
	{
		return deposit == null ? deposit = new ArrayList<>() : deposit;
	}

	public List<String> getWithdraw()
	{
		return withdraw == null ? withdraw = new ArrayList<>() : withdraw;
	}

	/** Replaces a list with the non-empty lines of some typed text. */
	public static List<String> lines(String text)
	{
		List<String> lines = new ArrayList<>();
		if (text == null)
		{
			return lines;
		}
		for (String line : text.split("\n"))
		{
			line = line.trim();
			if (!line.isEmpty() && lines.size() < MAX_LINES)
			{
				lines.add(line.length() > MAX_LINE ? line.substring(0, MAX_LINE) : line);
			}
		}
		return lines;
	}

	public static List<Line> parse(List<String> lines)
	{
		List<Line> parsed = new ArrayList<>();
		for (String line : lines)
		{
			for (String item : items(line))
			{
				parsed.add(new Line(item));
			}
		}
		return parsed;
	}

	/**
	 * The items on a line: one, unless commas were used to list several. A comma is for a number
	 * ("Xeric's aid, 3"), so one followed by anything but a number starts the next item: "Overload, Xeric's aid, 3"
	 * is an Overload and three aids.
	 */
	static List<String> items(String line)
	{
		List<String> items = new ArrayList<>();
		StringBuilder item = new StringBuilder();
		for (String part : line.split(",", -1))
		{
			// a number, which may go on with the next choice: "*chinchompa, 500 & Twisted buckler"
			if (item.length() > 0 && !part.trim().isEmpty() && !part.trim().matches("\\d+(\\s*[&|].*)?"))
			{
				items.add(item.toString().trim());
				item.setLength(0);
			}
			item.append(item.length() == 0 ? "" : ",").append(part);
		}
		items.add(item.toString().trim());
		return items;
	}

	/**
	 * Adds to or takes from the line for an item, keeping the count in the "Name, N" suffix.
	 * Only a plain line for the item's base name is touched, never a wildcard, an "A | B" or an "A & B"; the line is
	 * added at the end when there is none and dropped when its count reaches zero.
	 *
	 * @return whether the lines changed
	 */
	public static boolean mark(List<String> lines, String itemName, int delta)
	{
		String name = baseName(itemName);
		for (int i = 0; i < lines.size(); i++)
		{
			Line line = new Line(lines.get(i));
			if (line.plain() && !line.everything && line.name.equalsIgnoreCase(name))
			{
				int count = line.count + delta;
				if (count <= 0)
				{
					lines.remove(i);
				}
				else
				{
					lines.set(i, count > 1 ? name + ", " + count : name);
				}
				return true;
			}
		}
		if (delta > 0 && lines.size() < MAX_LINES)
		{
			lines.add(delta > 1 ? name + ", " + delta : name);
			return true;
		}
		return false;
	}

	/** "Xeric's aid(4)" and "Toxic blowpipe (charged)" become "Xeric's aid" and "Toxic blowpipe". */
	static String baseName(String itemName)
	{
		int paren = itemName.indexOf('(');
		return paren > 0 ? itemName.substring(0, paren).trim() : itemName.trim();
	}
}

package com.coxstorageplanner;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * A chest's plan checked against the inventory right now, in three phases: gear to wear first, then
 * deposits, then withdrawals. A deposit is done when none of the item is left, or, for a line with a
 * number, when that many went in since the storage was opened or are already in it; "everything else"
 * is done when nothing is carried that the take-out list doesn't keep. A withdrawal is done when the
 * inventory and worn equipment together hold the number asked for; the same item on a later line asks
 * for that many more; one whose item is nowhere, not on you and not in the storage, is skipped. A "wear"
 * line is done once it's worn, and skipped when there's no more of it to put on. An "A | B & C" line is settled first ({@link #settle}): the first choice
 * that's all to be had, and the others aren't asked for or kept. Potions light up fullest first. Numbers are quantities, so a stack of 14
 * juice counts as 14. Containers are maps of item name to quantity; a null storage is one the client
 * hasn't seen, so nothing is skipped for not being in it.
 *
 * <p>With putBack, an ordered plan is held to the slot: given the inventory slot by slot ({@link Carried})
 * it goes by {@link ChestLayout}, where a withdrawal is done when its slot holds it and anything in
 * the wrong slot goes back in. Without the slots it only asks back what belongs to a later step.
 *
 * <p>Held to the slot, something out of place goes in before the next withdrawal, as soon as it is.
 * A storage that's full turns the phases into rounds: put in what fits, take out, put in the rest.
 * Every item takes a storage slot of its own; only a stackable one joins the stack already in there.
 * Held to the slot, a plan in a storage that tight also asks for drags inside the inventory ({@link Phase#MOVE}).
 */
public final class ChestProgress
{
	public static final class Step
	{
		public final ChestPlan.Line line;
		public final boolean deposit;
		public final boolean done;
		/** Position in the withdraw list, 1-based, 0 for deposits. */
		public final int order;
		/** A withdrawal or gear to wear skipped because no more of the item is on you or in the storage; done as well. */
		public final boolean missing;
		/** How many more still to move, so only that many light up; MAX_VALUE for all of them. */
		public final int remaining;
		/**
		 * Withdrawals: the number of this step's next click, counting every click of the plan from 1.
		 * "Xeric's aid, 2" is two clicks, a stack is one, and a skipped step is none.
		 */
		public final int click;
		/**
		 * Withdrawals: clicks still to make before this step's next one, 0 for the very next click;
		 * MAX_VALUE for one that can't be made yet. The clicks are numbered by it, from 1.
		 */
		public final int rank;
		/** Withdrawals: how many clicks of the step can be made now, one after the other. */
		public final int now;
		/** Withdrawals: whether it comes out as one stack, so one click whatever the count. */
		public final boolean stack;
		/** Withdrawals: the number of the step's first click, done ones included. */
		public final int first;
		/** Withdrawals: how many clicks the step is; 0 for one that's worn or nowhere to be found, which has no number. */
		public final int span;

		Step(ChestPlan.Line line, boolean deposit, boolean done, int order, int remaining)
		{
			this(line, deposit, done, order, false, remaining, 0, 0, false, 0, 0, 0);
		}

		Step(ChestPlan.Line line, boolean deposit, boolean done, int order, boolean missing, int remaining,
			int click, int rank, boolean stack, int first, int span, int now)
		{
			this.now = now;
			this.first = first;
			this.span = span;
			this.line = line;
			this.deposit = deposit;
			this.done = done;
			this.order = order;
			this.missing = missing;
			this.remaining = done ? 0 : remaining;
			this.click = click;
			this.rank = rank;
			this.stack = stack;
		}
	}

	public enum Phase
	{
		WEAR, DEPOSIT, WITHDRAW,
		/** Drag an item to the slot it belongs in. */
		MOVE,
		/** Use a potion on another of its kind, to make a fuller dose. */
		MIX
	}

	/** Two partial doses of a potion carried, to use one on the other ({@link #topUp}). */
	public static final class Mix
	{
		/** The potion to use, and the one to use it on. */
		public final String from;
		public final String to;
		/** Their inventory slots, -1 without the slots. */
		public final int fromSlot;
		public final int toSlot;

		private Mix(String from, String to, int fromSlot, int toSlot)
		{
			this.from = from;
			this.to = to;
			this.fromSlot = fromSlot;
			this.toSlot = toSlot;
		}
	}

	/** The inventory slot by slot, and how the storage stands. */
	public static final class Carried
	{
		/** Item names by inventory slot, null for an empty one. */
		final String[] names;
		final int[] quantities;
		/** Storage slots left, negative when that isn't known. */
		final int free;
		/** Whether the last look at this storage was in a round of withdrawals, so the round gets finished. */
		final boolean withdrawing;
		/** Whether that round was of withdrawals into whatever slots were empty ({@link ChestProgress#loose}). */
		final boolean loose;
		/** The clicks the numbers leave out ({@link ChestProgress#numbered}), null to number from the next click. */
		final boolean[] numbered;

		public Carried(String[] names, int[] quantities, int free, boolean withdrawing)
		{
			this(names, quantities, free, withdrawing, false);
		}

		public Carried(String[] names, int[] quantities, int free, boolean withdrawing, boolean loose)
		{
			this(names, quantities, free, withdrawing, loose, null);
		}

		public Carried(String[] names, int[] quantities, int free, boolean withdrawing, boolean loose, boolean[] numbered)
		{
			this.names = names;
			this.quantities = quantities;
			this.free = free;
			this.withdrawing = withdrawing;
			this.loose = loose;
			this.numbered = numbered;
		}

		public Carried(List<String> names)
		{
			this(names.toArray(new String[0]), ones(names.size()), -1, false);
		}

		public Carried with(int free, boolean withdrawing, boolean loose)
		{
			return new Carried(names, quantities, free, withdrawing, loose, numbered);
		}

		public Carried with(int free, boolean withdrawing, boolean loose, boolean[] numbered)
		{
			return new Carried(names, quantities, free, withdrawing, loose, numbered);
		}

		private static int[] ones(int n)
		{
			int[] ones = new int[n];
			java.util.Arrays.fill(ones, 1);
			return ones;
		}
	}

	/** A withdrawal that can be made right now, by slot: its step and its number in the plan. */
	public static final class Click
	{
		public final Step step;
		public final int number;

		private Click(Step step, int number)
		{
			this.step = step;
			this.number = number;
		}
	}

	public final ChestPlan plan;
	/** Gear to put on, before anything else. */
	public final List<Step> wears;
	public final List<Step> deposits;
	public final List<Step> withdrawals;
	/**
	 * Carried items to put back before taking out: in the wrong slot, or without the slots, of a later step.
	 * One that gets dragged to its slot instead ({@link #drags}) isn't among them.
	 */
	public final List<String> outOfOrder;
	/** Clicks the whole take-out list comes to, skipped steps left out. */
	public final int clicks;
	/** Storage slots left, negative when that isn't known. */
	public final int free;
	/** Things still have to go in, but the storage is full and nothing can come out to make room. */
	public final boolean blocked;
	/** Whether a round of withdrawals is on, to hand back in with the next {@link Carried}. */
	public final boolean withdrawing;
	/** What the storage holds, null when the client hasn't seen it. */
	private final Map<String, Integer> storage;
	private final List<ChestPlan.Line> takeOut;
	/** A potion to use on another before anything else, null for none. */
	private final Mix mix;
	private final Phase phase;
	/** The plan slot by slot, null when it goes by counts. */
	private final ChestLayout layout;
	private final Carried carried;
	/** With a layout, the withdrawals that can be made now, in click order. */
	private final List<Click> queue;
	/** With a layout, the same plan going by counts alone: what's carried, whatever slot it's in. */
	private final ChestProgress counts;
	private final Set<String> stackable;
	/** Per click of the plan, from 1, whether it was made already when the numbering began. */
	private final boolean[] numbered;
	/** How many withdrawals can be made now, one after the other. */
	private final int toClick;

	public ChestProgress(ChestPlan plan, Map<String, Integer> inventory)
	{
		this(plan, inventory, Collections.emptyMap(), inventory, null);
	}

	public ChestProgress(ChestPlan plan, Map<String, Integer> inventory, Map<String, Integer> openedWith, Map<String, Integer> storage)
	{
		this(plan, inventory, Collections.emptyMap(), openedWith, storage);
	}

	/**
	 * @param worn what's equipped, which counts as withdrawn too so gear you put on stays ticked off
	 * @param openedWith the inventory when the storage was opened
	 * @param storage what the storage holds now, null if the client hasn't seen it
	 */
	public ChestProgress(ChestPlan plan, Map<String, Integer> inventory, Map<String, Integer> worn,
		Map<String, Integer> openedWith, Map<String, Integer> storage)
	{
		this(plan, inventory, worn, openedWith, storage, false);
	}

	/** @param putBack whether an ordered plan wants carried items of later steps put back first */
	public ChestProgress(ChestPlan plan, Map<String, Integer> inventory, Map<String, Integer> worn,
		Map<String, Integer> openedWith, Map<String, Integer> storage, boolean putBack)
	{
		this(plan, inventory, worn, openedWith, storage, putBack, Collections.emptySet());
	}

	/** @param stackable names of the items that stack, which come out in one click whatever the count */
	public ChestProgress(ChestPlan plan, Map<String, Integer> inventory, Map<String, Integer> worn,
		Map<String, Integer> openedWith, Map<String, Integer> storage, boolean putBack, Set<String> stackable)
	{
		this(plan, inventory, worn, openedWith, storage, putBack, stackable, null);
	}

	/** @param carried the inventory slot by slot and the room in the storage, null to go by counts alone */
	public ChestProgress(ChestPlan plan, Map<String, Integer> inventory, Map<String, Integer> worn,
		Map<String, Integer> openedWith, Map<String, Integer> storage, boolean putBack, Set<String> stackable, Carried carried)
	{
		this.plan = plan;
		this.storage = storage;
		this.carried = carried;
		this.stackable = stackable;
		this.free = carried == null ? -1 : carried.free;
		Map<String, Integer> held = storage == null ? Collections.emptyMap() : storage;
		List<ChestPlan.Line> takeOut = settle(ChestPlan.parse(plan.getWithdraw()), inventory, worn, storage);
		List<ChestPlan.Line> putIn = ChestPlan.parse(plan.getDeposit());
		Mix mix = null;
		if (plan.isTopUp())
		{
			TopUp swapped = topUp(takeOut, putIn, inventory, worn, storage, carried);
			takeOut = swapped.lines;
			mix = swapped.mix;
		}
		this.mix = mix;
		this.takeOut = takeOut;
		List<Step> wears = new ArrayList<>();
		boolean carries = false;
		for (ChestPlan.Line line : takeOut)
		{
			if (line.wear)
			{
				int on = count(line, worn);
				// no more of it to put on, carried or in the storage: skipped like a withdrawal that's nowhere,
				// so arrows shot down below their number don't hold up everything after them
				boolean missing = on < line.count && storage != null && count(line, inventory) == 0 && count(line, storage) == 0;
				wears.add(new Step(line, false, on >= line.count || missing, 0, missing, line.count - on, 0, 0, false, 0, 0, 0));
			}
			carries |= !line.wear;
		}
		// per put-in line: how many more it takes, and whether none of its item is left
		int[] budgets = new int[putIn.size()];
		boolean[] gone = new boolean[putIn.size()];
		for (int j = 0; j < putIn.size(); j++)
		{
			ChestPlan.Line line = putIn.get(j);
			budgets[j] = Integer.MAX_VALUE;
			if (line.everythingElse)
			{
				gone[j] = true;
				for (String name : inventory.keySet())
				{
					gone[j] &= keeps(takeOut, name);
				}
			}
			else
			{
				int left = count(line, inventory);
				gone[j] = left == 0;
				if (line.counted)
				{
					int in = Math.max(count(line, openedWith) - left, count(line, held));
					budgets[j] = Math.max(0, line.count - in);
				}
			}
		}
		ChestLayout layout = carried != null && putBack && plan.isOrdered() && carries
			? new ChestLayout(takeOut, putIn, budgets, carried.names, carried.quantities, worn, storage, carried.free,
				stackable, carried.withdrawing, carried.loose)
			: null;
		this.layout = layout;
		this.counts = layout == null ? null : new ChestProgress(plan, inventory, worn, openedWith, storage, false, stackable, carried);

		List<Step> deposits = new ArrayList<>();
		List<Step> withdrawals = new ArrayList<>();
		List<String> outOfOrder = new ArrayList<>();
		List<Click> queue = new ArrayList<>();
		// the clicks of the plan, from 1, that are made already
		java.util.BitSet madeClicks = new java.util.BitSet();
		if (layout != null)
		{
			for (int j = 0; j < putIn.size(); j++)
			{
				boolean done = true;
				for (int slot : layout.wrong)
				{
					done &= layout.via[slot] != j;
				}
				deposits.add(new Step(putIn.get(j), true, done, 0, budgets[j]));
			}
			Set<Integer> dragged = new java.util.HashSet<>();
			for (int[] move : layout.moves)
			{
				dragged.add(move[0]);
			}
			for (int slot : layout.wrong)
			{
				if (layout.via[slot] == ChestLayout.MISPLACED && !dragged.contains(slot) && !outOfOrder.contains(carried.names[slot]))
				{
					outOfOrder.add(carried.names[slot]);
				}
			}
			Step[] byLine = new Step[takeOut.size()];
			int order = 0;
			for (int i = 0; i < takeOut.size(); i++)
			{
				ChestPlan.Line line = takeOut.get(i);
				if (line.wear)
				{
					continue;
				}
				int any = -1;
				int total = 0;
				int first = -1;
				int more = 0;
				int rank = -1;
				int now = 0;
				boolean stack = false;
				for (int k = 0; k < layout.entries.size(); k++)
				{
					ChestLayout.Entry entry = layout.entries.get(k);
					if (entry.index != i)
					{
						continue;
					}
					any = any < 0 ? k : any;
					total++;
					stack = entry.stack;
					int queued = layout.queue.indexOf(k);
					if (queued >= 0)
					{
						rank = rank < 0 ? queued : rank;
						now++;
					}
					if (!layout.placed[k] || layout.shortBy[k] > 0)
					{
						first = first < 0 ? k : first;
						more += !entry.stack ? 1 : layout.placed[k] ? layout.shortBy[k] : entry.want;
					}
				}
				// no slot of its own: worn, or nowhere to get it from
				boolean missing = any < 0 && !layout.worn[i];
				byLine[i] = new Step(line, false, first < 0, ++order, missing, more,
					(first >= 0 ? first : any >= 0 ? any : layout.entries.size()) + 1, first < 0 ? 0 : rank < 0 ? Integer.MAX_VALUE : rank, stack,
					any + 1, total, now);
				withdrawals.add(byLine[i]);
			}
			for (int k : layout.queue)
			{
				queue.add(new Click(byLine[layout.entries.get(k).index], k + 1));
			}
			this.clicks = layout.entries.size();
			this.toClick = layout.queue.size();
			for (int k = 0; k < layout.entries.size(); k++)
			{
				madeClicks.set(k + 1, layout.placed[k] && layout.shortBy[k] == 0);
			}
		}
		else
		{
			for (int j = 0; j < putIn.size(); j++)
			{
				ChestPlan.Line line = putIn.get(j);
				deposits.add(new Step(line, true, gone[j] || budgets[j] == 0, 0, line.counted ? budgets[j] : Integer.MAX_VALUE));
			}
			// what's left on you and in the storage for the steps further down, once the ones before took theirs:
			// "Xeric's aid" twice means two of them, and "Xeric's aid, 2" then "*aid*" three
			Map<String, Integer> wornLeft = new HashMap<>(worn);
			Map<String, Integer> carriedLeft = new HashMap<>(inventory);
			Map<String, Integer> left = storage == null ? null : new HashMap<>(storage);
			int order = 0;
			int clicks = 0;
			int pending = 0;
			for (ChestPlan.Line line : takeOut)
			{
				if (line.wear)
				{
					continue;
				}
				int fromWorn = take(line, wornLeft, line.count);
				int got = fromWorn + take(line, carriedLeft, line.count - fromWorn);
				boolean done = got >= line.count;
				int remaining = line.count - got;
				int there = done ? 0 : left == null ? remaining : take(line, left, remaining);
				// nowhere to get it from: skip the step rather than wait on it forever
				boolean missing = !done && left != null && there == 0;
				boolean stack = stacks(line, stackable, inventory) || stacks(line, stackable, held);
				int mine = stack ? (done || there > 0 ? 1 : 0) : got + there;
				int made = stack ? (done ? 1 : 0) : got;
				withdrawals.add(new Step(line, false, done || missing, ++order, missing, remaining, clicks + made + 1, pending, stack,
					clicks + 1, mine, mine - made));
				madeClicks.set(clicks + 1, clicks + 1 + made);
				clicks += mine;
				pending += mine - made;
			}
			this.clicks = clicks;
			this.toClick = pending;
			if (putBack && plan.isOrdered())
			{
				int next = 0;
				while (next < withdrawals.size() && withdrawals.get(next).done)
				{
					next++;
				}
				for (String name : inventory.keySet())
				{
					// carried, not wanted by the next step or one already done, but by one further on
					boolean early = false;
					boolean later = false;
					for (int i = 0; i < withdrawals.size(); i++)
					{
						if (withdrawals.get(i).line.matches(name))
						{
							early |= i <= next;
							later |= i > next;
						}
					}
					if (later && !early)
					{
						outOfOrder.add(name);
					}
				}
			}
		}
		this.wears = Collections.unmodifiableList(wears);
		this.deposits = Collections.unmodifiableList(deposits);
		this.withdrawals = Collections.unmodifiableList(withdrawals);
		this.outOfOrder = Collections.unmodifiableList(outOfOrder);
		this.queue = Collections.unmodifiableList(queue);
		boolean[] done = new boolean[this.clicks + 1];
		for (int click = 1; click < done.length; click++)
		{
			done[click] = madeClicks.get(click);
		}
		// the numbers stay as they were handed in while that still fits: the same list, and nothing it left out undone since
		boolean[] from = carried == null ? null : carried.numbered;
		boolean fits = from != null && from.length == done.length;
		for (int click = 1; fits && click < done.length; click++)
		{
			fits = !from[click] || done[click];
		}
		this.numbered = fits ? from : done;

		boolean round;
		boolean stuck;
		if (layout != null)
		{
			round = layout.withdrawing;
			stuck = layout.blocked;
		}
		else if (allDone(deposits) && outOfOrder.isEmpty())
		{
			round = true;
			stuck = false;
		}
		else
		{
			// a full storage: take things out to make room, and finish that round before putting more in
			boolean room = free != 0 || storage == null;
			boolean space = carried == null;
			for (int slot = 0; carried != null && slot < carried.names.length; slot++)
			{
				String name = carried.names[slot];
				space |= name == null;
				room |= name != null && freeDeposit(name) && (pendingDeposit(name) != null || outOfOrder.contains(name));
			}
			boolean out = space && !allDone(withdrawals);
			round = carried != null && carried.withdrawing ? out || !room : !room;
			stuck = !room && !out;
			round &= out;
		}
		this.withdrawing = round;
		this.blocked = stuck;
		this.phase = !allDone(wears) ? Phase.WEAR : mix != null ? Phase.MIX : layout != null && layout.moving ? Phase.MOVE
			: round ? Phase.WITHDRAW : Phase.DEPOSIT;
	}

	/**
	 * The take-out list with each "A | B & C" line turned into the items of one of its choices: the first
	 * whose items are all to be had, on you or in the storage, in the numbers asked for. So with the bow
	 * around, the chinchompas and the buckler of "Venator bow | *chinchompa & Twisted buckler" aren't asked
	 * for, don't light up and aren't kept. With no choice complete, a line of single items under one count
	 * ("Ayak | Sang* staff*") stays as it is and takes any of them; any other goes by the first choice
	 * there's something of, or the very first. A storage the client hasn't seen counts as empty here.
	 */
	static List<ChestPlan.Line> settle(List<ChestPlan.Line> lines, Map<String, Integer> inventory, Map<String, Integer> worn,
		Map<String, Integer> storage)
	{
		List<ChestPlan.Line> settled = new ArrayList<>();
		for (ChestPlan.Line line : lines)
		{
			if (line.options.isEmpty() || line.everything || line.everythingElse)
			{
				settled.add(line);
				continue;
			}
			List<ChestPlan.Line> complete = null;
			List<ChestPlan.Line> begun = null;
			for (List<ChestPlan.Line> option : line.options)
			{
				boolean all = true;
				boolean any = false;
				for (ChestPlan.Line item : option)
				{
					int have = count(item, inventory) + count(item, worn) + (storage == null ? 0 : count(item, storage));
					all &= have >= item.count;
					any |= have > 0;
				}
				if (all)
				{
					complete = option;
					break;
				}
				begun = begun == null && any ? option : begun;
			}
			if (complete == null && line.either)
			{
				settled.add(line);
			}
			else
			{
				settled.addAll(complete != null ? complete : begun != null ? begun : line.options.get(0));
			}
		}
		return settled;
	}

	/** What {@link #topUp} makes of the take-out list. */
	private static final class TopUp
	{
		final List<ChestPlan.Line> lines;
		final Mix mix;

		TopUp(List<ChestPlan.Line> lines, Mix mix)
		{
			this.lines = lines;
			this.mix = mix;
		}
	}

	/**
	 * The take-out list with its potions swapped for fuller doses. A potion line's number is made up of the
	 * best doses to be had, on you or in the storage (a carried dose over the same dose in there), so when the
	 * storage holds a fuller dose than one you carry, the carried one goes in (a deposit added to {@code putIn},
	 * reading "Overload (1/2)") and the line takes only doses from the fullest kept down, so "Overload, 1" with
	 * an Overload (2) carried and a (4) in the storage is put the (2) in, take the (4) out. A carried dose
	 * below the ones kept goes in whether or not something comes out for it. Lines of the same name pool their numbers.
	 *
	 * <p>When the fullest doses to be had are fewer than the line wants, partial doses are decanted: two partial
	 * doses carried are a {@link Mix} (the smaller to use on the larger) before anything else; with one or none
	 * carried, the partial doses in the storage that make up the difference are a withdrawal added to the end
	 * of the list (reading "Overload (1/3)"), as long as the inventory has a slot for them. Once no mixing
	 * helps, the swap above puts what's left over back in.
	 *
	 * <p>A line changes only when a swap or a mix comes of it, only when all its items are potions, and only
	 * once the storage has been seen.
	 */
	static TopUp topUp(List<ChestPlan.Line> takeOut, List<ChestPlan.Line> putIn, Map<String, Integer> inventory,
		Map<String, Integer> worn, Map<String, Integer> storage, Carried carried)
	{
		if (storage == null)
		{
			return new TopUp(takeOut, null);
		}
		List<ChestPlan.Line> lines = new ArrayList<>(takeOut);
		Set<String> seen = new java.util.HashSet<>();
		Mix mix = null;
		boolean space = carried == null;
		for (int slot = 0; carried != null && slot < carried.names.length; slot++)
		{
			space |= carried.names[slot] == null;
		}
		for (int i = 0; i < takeOut.size(); i++)
		{
			ChestPlan.Line line = takeOut.get(i);
			if (!swappable(line) || !seen.add(line.name.toLowerCase(java.util.Locale.ROOT)) || count(line, worn) > 0)
			{
				continue;
			}
			List<Integer> group = new ArrayList<>();
			int want = 0;
			for (int j = i; j < takeOut.size(); j++)
			{
				if (swappable(takeOut.get(j)) && takeOut.get(j).name.equalsIgnoreCase(line.name))
				{
					group.add(j);
					want += takeOut.get(j).count;
				}
			}
			List<Integer> held = doses(line, inventory);
			List<Integer> stored = doses(line, storage);
			if (held == null || stored == null || held.isEmpty() && stored.isEmpty())
			{
				continue;
			}
			// the best doses of the lot as they are: the fullest first, a carried one before the same dose in the storage
			int c = 0;
			int s = 0;
			int floor = -1;
			int kept = 0;
			for (int u = 0; u < want && (c < held.size() || s < stored.size()); u++)
			{
				if (s >= stored.size() || (c < held.size() && held.get(c) >= stored.get(s)))
				{
					floor = held.get(c++);
				}
				else
				{
					floor = stored.get(s++);
				}
				kept += floor;
			}
			// and the best with the partial doses decanted: everything, up to four a potion
			int total = 0;
			int fours = 0;
			for (List<Integer> some : java.util.Arrays.asList(held, stored))
			{
				for (int dose : some)
				{
					total += dose;
					fours += dose == FULL ? 1 : 0;
				}
			}
			if (Math.min(total, FULL * want) > kept)
			{
				List<Integer> partial = new ArrayList<>();
				int carriedDoses = 0;
				for (int dose : held)
				{
					if (dose < FULL)
					{
						partial.add(dose);
						carriedDoses += dose;
					}
				}
				if (partial.size() >= 2)
				{
					if (mix == null)
					{
						mix = mix(line, carried, inventory, partial.get(partial.size() - 1), partial.get(0));
					}
					continue;
				}
				int needed = Math.min(total, FULL * want) - FULL * Math.min(want, fours);
				int take = 0;
				int lowest = FULL;
				StringBuilder which = new StringBuilder();
				for (int dose : stored)
				{
					if (dose < FULL && carriedDoses < needed)
					{
						carriedDoses += dose;
						take++;
						which.insert(0, dose != lowest ? dose + (which.length() == 0 ? "" : "/") : "");
						lowest = dose;
					}
				}
				if (take > 0 && space)
				{
					lines.add(line.doses(lowest, FULL - 1, line.name + " (" + which + ")", take, true));
					continue;
				}
			}
			if (c >= held.size() || held.get(c) >= floor)
			{
				continue;
			}
			StringBuilder out = new StringBuilder();
			for (int k = held.size() - 1; k >= c; k--)
			{
				if (out.length() == 0 || !held.get(k).equals(held.get(k + 1)))
				{
					out.append(out.length() == 0 ? "" : "/").append(held.get(k));
				}
			}
			for (int j : group)
			{
				ChestPlan.Line member = takeOut.get(j);
				lines.set(j, member.doses(floor, Integer.MAX_VALUE, null, member.count, member.counted));
			}
			putIn.add(line.doses(0, floor - 1, line.name + " (" + out + ")", 1, false));
		}
		return new TopUp(lines, mix);
	}

	/** The most doses a potion holds. */
	static final int FULL = 4;

	/**
	 * Two partial doses of a line's potion carried, the first to use on the second. With the slots known they're
	 * the first two slots holding one, the later used on the earlier: the game fills the potion used on, and the
	 * earlier slot is the one the plan put the potion in, so the full dose ends up where it belongs. Without the
	 * slots, the smaller dose used on the larger.
	 */
	private static Mix mix(ChestPlan.Line line, Carried carried, Map<String, Integer> inventory, int smallest, int largest)
	{
		if (carried != null)
		{
			int to = -1;
			for (int slot = 0; slot < carried.names.length; slot++)
			{
				String name = carried.names[slot];
				if (name == null || !line.matches(name) || dose(name) >= FULL)
				{
					continue;
				}
				if (to < 0)
				{
					to = slot;
				}
				else
				{
					return new Mix(name, carried.names[to], slot, to);
				}
			}
		}
		String from = null;
		String to = null;
		for (String name : inventory.keySet())
		{
			if (line.matches(name))
			{
				from = from == null && dose(name) == smallest ? name : from;
				to = to == null && dose(name) == largest ? name : to;
			}
		}
		return new Mix(from, to, -1, -1);
	}

	/** Whether {@link #topUp} may change a take-out line: one item to carry, as written. */
	private static boolean swappable(ChestPlan.Line line)
	{
		return !line.wear && !line.everything && !line.everythingElse && line.options.isEmpty();
	}

	/**
	 * The doses of a line's items in a container, one per unit, the fullest first; null when an item there
	 * has no dose, so the line isn't about potions.
	 */
	private static List<Integer> doses(ChestPlan.Line line, Map<String, Integer> items)
	{
		List<Integer> doses = new ArrayList<>();
		for (Map.Entry<String, Integer> e : items.entrySet())
		{
			if (e.getValue() > 0 && line.matches(e.getKey()))
			{
				int dose = dose(e.getKey());
				if (dose < 0)
				{
					return null;
				}
				for (int u = 0; u < e.getValue(); u++)
				{
					doses.add(dose);
				}
			}
		}
		doses.sort(Collections.reverseOrder());
		return doses;
	}

	/** Whether the take-out list keeps an item, so "everything else" leaves it alone. A dose swapped out isn't kept. */
	static boolean keeps(List<ChestPlan.Line> takeOut, String itemName)
	{
		for (ChestPlan.Line line : takeOut)
		{
			if (line.matches(itemName))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * What to do now: wear the gear, then put things in, then take things out. When the storage can't
	 * hold it all the last two alternate: withdrawals while nothing more fits, until that round is through,
	 * with drags in between for what's carried in the wrong slot.
	 */
	public Phase phase()
	{
		return phase;
	}

	/** Whether the plan is held to the slot: an ordered list, the put-back setting, and the inventory's slots known. */
	public boolean exact()
	{
		return layout != null;
	}

	private static boolean allDone(List<Step> steps)
	{
		for (Step step : steps)
		{
			if (!step.done)
			{
				return false;
			}
		}
		return true;
	}

	static int count(ChestPlan.Line line, Map<String, Integer> items)
	{
		int count = 0;
		for (Map.Entry<String, Integer> e : items.entrySet())
		{
			if (line.matches(e.getKey()))
			{
				count += e.getValue();
			}
		}
		return count;
	}

	/** Takes up to {@code want} of a line's items out of a container map. @return how many it got */
	static int take(ChestPlan.Line line, Map<String, Integer> items, int want)
	{
		int taken = 0;
		for (Map.Entry<String, Integer> e : items.entrySet())
		{
			if (taken < want && e.getValue() > 0 && line.matches(e.getKey()))
			{
				int some = Math.min(want - taken, e.getValue());
				e.setValue(e.getValue() - some);
				taken += some;
			}
		}
		return taken;
	}

	static boolean stacks(ChestPlan.Line line, Set<String> stackable, Map<String, Integer> items)
	{
		if (stackable.isEmpty())
		{
			return false;
		}
		for (String name : items.keySet())
		{
			if (stackable.contains(name) && line.matches(name))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Take-out lines that rebuild a loadout: the items in the order given (worn gear first, then the
	 * inventory slot by slot), a run of the same item merged into one line with its number. Dose
	 * suffixes go, so "Xeric's aid(4)" becomes "Xeric's aid". Nulls (empty slots) are skipped.
	 *
	 * @param quantities stack sizes, matching names
	 * @param prefix put before each line, "wear " for gear
	 */
	public static List<String> loadoutLines(List<String> names, List<Integer> quantities, String prefix)
	{
		List<String> lines = new ArrayList<>();
		String last = null;
		int count = 0;
		for (int i = 0; i <= names.size(); i++)
		{
			String name = i < names.size() ? names.get(i) : null;
			if (name != null)
			{
				name = DOSES.matcher(name).replaceFirst("");
			}
			if (name != null && name.equals(last))
			{
				count += quantities.get(i);
				continue;
			}
			if (last != null)
			{
				lines.add(prefix + (count > 1 ? last + ", " + count : last));
			}
			last = name;
			count = name == null ? 0 : quantities.get(i);
		}
		return lines;
	}

	private static final Pattern DOSES = Pattern.compile("\\(\\d\\)$");

	/** Item names, one per unit, to a container map; nulls (empty slots) are skipped. */
	public static Map<String, Integer> tally(List<String> names)
	{
		Map<String, Integer> items = new LinkedHashMap<>();
		for (String name : names)
		{
			if (name != null)
			{
				items.merge(name, 1, Integer::sum);
			}
		}
		return items;
	}

	/** The withdrawal to do next in an ordered plan, null when done or not ordered. */
	public Step next()
	{
		if (!plan.isOrdered())
		{
			return null;
		}
		if (!queue.isEmpty())
		{
			return queue.get(0).step;
		}
		for (Step step : withdrawals)
		{
			if (!step.done)
			{
				return step;
			}
		}
		return null;
	}

	public boolean isDone()
	{
		return allDone(wears) && mix == null
			&& (layout != null ? layout.done() : allDone(deposits) && outOfOrder.isEmpty() && allDone(withdrawals));
	}

	/** The potion to use on another right now, null in any other phase. */
	public Mix mix()
	{
		return phase == Phase.MIX ? mix : null;
	}

	/**
	 * Whether the chest has been seen to: the gear is on, what goes in is in and what comes out is
	 * carried, in whatever slots. A plan held to the slot can have this and still not be {@link #isDone}.
	 */
	public boolean isStocked()
	{
		return counts == null ? isDone() : counts.isDone();
	}

	/** Whether an item, in the storage or the inventory, is gear still to put on. */
	public boolean highlightsWear(String itemName)
	{
		return wearStep(itemName) != null;
	}

	/** The wear step an item, in the storage or the inventory, is gear still to put on for, or null. */
	public Step wearStep(String itemName)
	{
		if (phase() != Phase.WEAR)
		{
			return null;
		}
		for (Step step : wears)
		{
			if (!step.done && step.line.matches(itemName))
			{
				return step;
			}
		}
		return null;
	}

	/** Whether an item in the side inventory should light up: something still to put in. */
	public boolean highlightsDeposit(String itemName)
	{
		if (layout != null)
		{
			if (phase == Phase.DEPOSIT)
			{
				for (int slot : layout.depositNow)
				{
					if (carried.names[slot].equals(itemName))
					{
						return true;
					}
				}
			}
			return false;
		}
		return depositStep(itemName) != null || (phase() == Phase.DEPOSIT && outOfOrder.contains(itemName));
	}

	/**
	 * Whether the item in an inventory slot goes in now. With the plan held to the slot it's that very
	 * slot, so of three aids only the one out of place lights; and only what the storage has room for.
	 * A slot that doesn't hold the item named (the caller's idea of slots isn't ours) goes by the name.
	 */
	public boolean depositsSlot(int slot, String itemName)
	{
		if (layout == null || slot < 0 || slot >= carried.names.length || !itemName.equals(carried.names[slot]))
		{
			return highlightsDeposit(itemName);
		}
		return phase == Phase.DEPOSIT && layout.depositNow.contains(slot);
	}

	/** The put-in step an inventory slot's item goes in for, null when it's just out of place (or not going in). */
	public Step depositStepAt(int slot, String itemName)
	{
		if (layout == null || slot < 0 || slot >= carried.names.length || !itemName.equals(carried.names[slot]))
		{
			return depositStep(itemName);
		}
		return phase == Phase.DEPOSIT && layout.via[slot] >= 0 ? deposits.get(layout.via[slot]) : null;
	}

	/** How many of an item go in now, with the plan held to the slot; for a caller that can't tell the slots apart. */
	public int depositsNamed(String itemName)
	{
		int count = 0;
		if (layout != null && phase == Phase.DEPOSIT)
		{
			for (int slot : layout.depositNow)
			{
				count += carried.names[slot].equals(itemName) ? 1 : 0;
			}
		}
		return count;
	}

	/** Whether putting an item in takes no storage slot: the room isn't known, or it joins a stack that's in there. */
	public boolean freeDeposit(String itemName)
	{
		return free < 0 || storage == null || (stackable.contains(itemName) && storage.containsKey(itemName));
	}

	/** The drags to make now, as {from, to} inventory slots, the next one first. Empty in any other phase. */
	public List<int[]> moves()
	{
		return phase == Phase.MOVE ? layout.moves : Collections.emptyList();
	}

	/**
	 * Whether the withdrawals to make now land out of place, in whatever slots are empty, and get dragged
	 * to their own after. To hand back in with the next {@link Carried}, like {@link #withdrawing}.
	 */
	public boolean loose()
	{
		return phase == Phase.WITHDRAW && layout != null && layout.loose;
	}

	/** Every drag the plan asks for, whether it's their turn yet or not. */
	public List<int[]> drags()
	{
		return layout == null ? Collections.emptyList() : layout.moves;
	}

	/** Whether one of {@link #outOfOrder} goes back in right now: it's the deposits' turn and the storage has room for it. */
	public boolean redepositsNow(String itemName)
	{
		if (phase != Phase.DEPOSIT)
		{
			return false;
		}
		if (layout == null)
		{
			return outOfOrder.contains(itemName);
		}
		for (int slot : layout.depositNow)
		{
			if (layout.via[slot] == ChestLayout.MISPLACED && carried.names[slot].equals(itemName))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * With the storage too full to put it back in: the inventory slot of an item to drag to the slot it
	 * belongs in, -1 when there's no such thing to do. What's in that slot swaps places with it.
	 */
	public int moveFrom()
	{
		return phase == Phase.MOVE ? layout.moves.get(0)[0] : phase == Phase.MIX ? mix.fromSlot : -1;
	}

	/** The inventory slot {@link #moveFrom} goes to. In the {@link Phase#MIX} phase the two are the potions, the one to use first. */
	public int moveTo()
	{
		return phase == Phase.MOVE ? layout.moves.get(0)[1] : phase == Phase.MIX ? mix.toSlot : -1;
	}

	/** The name of the item in an inventory slot, null for an empty one or without the slots. */
	public String nameAt(int slot)
	{
		return carried == null || slot < 0 || slot >= carried.names.length ? null : carried.names[slot];
	}

	/** The name of the item to drag, null for none. */
	public String moveName()
	{
		return nameAt(moveFrom());
	}

	/**
	 * The number a click of the plan is shown with. The clicks still to make when the storage was opened
	 * count from 1, and each keeps its number while the ones before it get made, so what's lit reads
	 * 1 2 3 4, then 2 3 4 5.
	 *
	 * @param click its place in the whole plan, from 1
	 */
	public int number(int click)
	{
		int number = click;
		for (int before = 1; before < click && before < numbered.length; before++)
		{
			number -= numbered[before] ? 1 : 0;
		}
		return number;
	}

	/** The number of a withdrawal step's next click. */
	public int number(Step step)
	{
		for (Click click : queue)
		{
			if (click.step == step)
			{
				return number(click.number);
			}
		}
		return number(step.click);
	}

	/** What the numbers leave out, to hand back in with the next {@link Carried} so they stay as they are. */
	public boolean[] numbered()
	{
		return numbered;
	}

	/** How many withdrawals can be made now, one after the other. */
	public int toClick()
	{
		return phase == Phase.WITHDRAW ? toClick : 0;
	}

	/** With the plan held to the slot: the withdrawals that can be made now, in click order. Empty in any other phase. */
	public List<Click> queue()
	{
		return phase == Phase.WITHDRAW ? queue : Collections.emptyList();
	}

	/**
	 * The deposit step an item in the side inventory still has to go in for, or null. Something
	 * carried out of order has no step; {@link #outOfOrder} lists it.
	 */
	public Step depositStep(String itemName)
	{
		if (phase() != Phase.DEPOSIT)
		{
			return null;
		}
		if (layout != null)
		{
			for (int slot : layout.depositNow)
			{
				if (carried.names[slot].equals(itemName) && layout.via[slot] >= 0)
				{
					return deposits.get(layout.via[slot]);
				}
			}
			return null;
		}
		return pendingDeposit(itemName);
	}

	/** The put-in step that still wants an item, whatever the phase. Going by counts. */
	private Step pendingDeposit(String itemName)
	{
		for (Step step : deposits)
		{
			if (step.done)
			{
				continue;
			}
			if (step.line.everythingElse)
			{
				if (!keeps(takeOut, itemName))
				{
					return step;
				}
			}
			else if (step.line.matches(itemName))
			{
				return step;
			}
		}
		return null;
	}

	/**
	 * The withdrawal step an item in the storage belongs to and hasn't been done, or null.
	 * With an ordered plan only steps within the next {@code limit} clicks count. Of the potions
	 * in the storage a step matches only the fullest lights up, so a 3-dose waits until the 4s are gone.
	 */
	public Step highlightsWithdraw(String itemName, int limit)
	{
		List<Step> steps = withdrawSteps(itemName, limit);
		return steps.isEmpty() ? null : steps.get(0);
	}

	/** Every step {@link #highlightsWithdraw} could mean, in order: "Xeric's aid" on two lines is two steps. */
	public List<Step> withdrawSteps(String itemName, int limit)
	{
		if (phase() != Phase.WITHDRAW)
		{
			return Collections.emptyList();
		}
		List<Step> steps = new ArrayList<>();
		if (layout != null)
		{
			for (int rank = 0; rank < queue.size() && rank < limit; rank++)
			{
				Step step = queue.get(rank).step;
				if (!steps.contains(step) && step.line.matches(itemName) && fullest(step.line, itemName))
				{
					steps.add(step);
				}
			}
			return steps;
		}
		for (Step step : withdrawals)
		{
			if (step.done)
			{
				continue;
			}
			if (plan.isOrdered() && step.rank >= limit)
			{
				break;
			}
			if (step.line.matches(itemName) && fullest(step.line, itemName))
			{
				steps.add(step);
			}
		}
		return steps;
	}

	/** Whether an item in the storage is what to click next: gear to wear, or the next withdrawal (any, unordered). */
	public boolean wantsNext(String itemName)
	{
		if (wearStep(itemName) != null)
		{
			return true;
		}
		return highlightsWithdraw(itemName, 1) != null;
	}

	/** Whether no fuller dose of this potion is in the storage; true for anything that isn't a potion. */
	boolean fullest(ChestPlan.Line line, String itemName)
	{
		int dose = dose(itemName);
		if (dose < 0 || storage == null)
		{
			return true;
		}
		for (String other : storage.keySet())
		{
			if (dose(other) > dose && line.matches(other))
			{
				return false;
			}
		}
		return true;
	}

	/** The N of a "(N)" dose suffix, -1 without one. */
	static int dose(String itemName)
	{
		java.util.regex.Matcher m = DOSES.matcher(itemName);
		return m.find() ? itemName.charAt(m.start() + 1) - '0' : -1;
	}
}

package com.coxstorageplanner;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Lights the storage's scroll arrow, up or down, when the item to click next is scrolled out of
 * view: gear to put on, or the next withdrawal.
 */
class ChestScrollOverlay extends Overlay
{
	private final Client client;
	private final CoxStoragePlannerPlugin plugin;
	private final CoxStoragePlannerConfig config;

	@Inject
	ChestScrollOverlay(Client client, CoxStoragePlannerPlugin plugin, CoxStoragePlannerConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.chestScrollHint())
		{
			return null;
		}
		ChestProgress progress = plugin.getOpenChest();
		int group = plugin.getOpenStorage();
		if (progress == null || group == 0)
		{
			return null;
		}
		boolean shared = group == InterfaceID.RAIDS_STORAGE_SHARED;
		Widget items = client.getWidget(shared ? InterfaceID.RaidsStorageShared.ITEMS : InterfaceID.RaidsStoragePrivate.ITEMS);
		Widget bar = client.getWidget(shared ? InterfaceID.RaidsStorageShared.SCROLLBAR : InterfaceID.RaidsStoragePrivate.SCROLLBAR);
		if (items == null || bar == null || items.isHidden() || items.getScrollHeight() <= items.getHeight())
		{
			return null;
		}
		Widget[] slots = items.getDynamicChildren();
		if (slots == null)
		{
			return null;
		}
		int top = items.getScrollY();
		int bottom = top + items.getHeight();
		int direction = 0;
		// of several identical items the last one is the one that glows
		java.util.Map<Integer, Widget> last = new java.util.LinkedHashMap<>();
		for (Widget slot : slots)
		{
			if (slot != null && slot.getItemId() > 0 && !slot.isHidden())
			{
				last.merge(slot.getItemId(), slot, (a, b) -> b.getIndex() > a.getIndex() ? b : a);
			}
		}
		for (Widget slot : last.values())
		{
			if (!progress.wantsNext(plugin.itemName(slot.getItemId())))
			{
				continue;
			}
			int middle = slot.getRelativeY() + slot.getHeight() / 2;
			if (middle >= top && middle <= bottom)
			{
				// one to click is in view already
				return null;
			}
			if (direction == 0)
			{
				direction = middle < top ? -1 : 1;
			}
		}
		Rectangle bounds = bar.getBounds();
		if (direction == 0 || bounds == null || bounds.width <= 0 || bounds.height < 2 * bounds.width)
		{
			return null;
		}
		// the arrows are the square ends of the bar
		int size = bounds.width;
		int y = direction < 0 ? bounds.y : bounds.y + bounds.height - size;
		Color color = config.chestGlowColor();
		double phase = (System.currentTimeMillis() % 800) / 800.0 * 2 * Math.PI;
		float strength = config.chestGlowPulse() ? (float) (0.65 + 0.35 * Math.sin(phase)) : 1f;
		graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), Math.round(110 * strength)));
		graphics.fillRect(bounds.x, y, size, size);
		graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), Math.round(255 * strength)));
		graphics.drawRect(bounds.x - 1, y - 1, size + 1, size + 1);
		graphics.drawRect(bounds.x - 2, y - 2, size + 3, size + 3);
		return null;
	}
}

package com.coxstorageplanner;

import java.util.Arrays;
import net.runelite.client.party.messages.PartyMemberMessage;

/** Sent to the party when the doses you carry or have stored change. */
public class CoxStorageMessage extends PartyMemberMessage
{
	/** Doses in the inventory. */
	private int[] carried;
	/** Private storage, null if they haven't opened it this raid. */
	private int[] stored;
	/** Shared storage as this member last saw it, null if they haven't opened it this raid. */
	private int[] shared;

	public CoxStorageMessage()
	{
	}

	public CoxStorageMessage(int[] carried, int[] stored, int[] shared)
	{
		this.carried = carried;
		this.stored = stored;
		this.shared = shared;
	}

	public int[] getCarried()
	{
		return carried;
	}

	public int[] getStored()
	{
		return stored;
	}

	public int[] getShared()
	{
		return shared;
	}

	public boolean sameContent(CoxStorageMessage other)
	{
		return other != null
			&& Arrays.equals(carried, other.carried)
			&& Arrays.equals(stored, other.stored)
			&& Arrays.equals(shared, other.shared);
	}
}

