		editor.addRow(takeOut, 2);
		editor.addRow(listArea(chestWithdraw, false), 3);
		editor.addRow(chestFlow, 8);
		editor.addRow(chestSteps, 6);
		chestEditor.setOpaque(false);
		chestEditor.add(editor, BorderLayout.CENTER);
