	private static void check(JCheckBox box, String tooltip)
	{
		box.setOpaque(false);
		box.setFont(FontManager.getRunescapeFont());
		box.setForeground(Color.WHITE);
		box.setBorder(new EmptyBorder(0, 0, 0, 0));
