		{
			Needs plan = needsFor(needsTabSolo);
			if (plan.set(potion, doses))
			{
				configManager.setConfiguration(CoxStoragePlannerConfig.GROUP,
					plan == needsSolo ? CoxStoragePlannerConfig.KEY_NEEDS_SOLO : CoxStoragePlannerConfig.KEY_NEEDS, plan.encode());
				refresh();
			}
		});
	}

	@Override
	public void setNeedsTab(boolean solo)
	{
		clientThread.invokeLater(() ->
		{
			if (inRaid)
			{
				// in a raid the switch overrides the party size, say to run the solo chests in a team of two
				raidSoloOverride = solo == soloRaid ? null : solo;
				updateOpenChest();
				refresh();
				return;
			}
			if (needsTabSolo != solo)
			{
				needsTabSolo = solo;
				configManager.setConfiguration(CoxStoragePlannerConfig.GROUP, CoxStoragePlannerConfig.KEY_NEEDS_TAB_SOLO, solo);
				refresh();
			}
		});
	}

	// ---- drawing ----

	/**
	 * Pushes the current state to the sidebar. Safe from any thread: the state is put together on the client
	 * thread, where everything it reads is written, and calls before that happens make one push between them.
	 */
	private void refresh()
	{
		if (panel != null && refreshQueued.compareAndSet(false, true))
		{
			clientThread.invokeLater(this::pushState);
		}
	}

	private void pushState()
	{
		refreshQueued.set(false);
		CoxStoragePanel target = panel;
		if (target == null)
		{
			return;
		}
		PanelState state = snapshot();
		boolean show = !config.hideSidebar() && (state.inRaid || atLobby || !config.hideOutsideRaid());
		SwingUtilities.invokeLater(() ->
		{
			if (panel != target)
			{
				// shut down in between
				return;
			}
			if (show != navigationShown)
			{
				navigationShown = show;
				if (show)
				{
					clientToolbar.addNavigation(navigationButton);
				}
				else
				{
					clientToolbar.removeNavigation(navigationButton);
				}
			}
			target.update(state);
		});
	}

	private void loadLineIcons()
	{
		lineIcons.clear();
		try
		{
			Map<String, Double> stored = gson.fromJson(config.lineIcons(), new com.google.gson.reflect.TypeToken<Map<String, Double>>()
			{
			}.getType());
			if (stored != null)
			{
				for (Map.Entry<String, Double> e : stored.entrySet())
				{
					if (e.getKey() != null && e.getValue() != null && e.getValue() > 0)
					{
						lineIcons.put(e.getKey(), e.getValue().intValue());
					}
				}
			}
		}
		catch (RuntimeException e)
		{
			// a broken config entry: the icons come back as the items are seen again
		}
	}

	/**
	 * Finds an item id for every line of the chest lists among the items seen so far, for the sidebar's
	 * icons. A line that matches several takes the fullest dose. Kept in the config, since outside a
	 * raid there's nothing to see them in.
	 */
	private void learnLineIcons(ChestBook book)
	{
		boolean changed = false;
		for (ChestPlan plan : book.all())
		{
			List<String> lines = new ArrayList<>(plan.getDeposit());
			lines.addAll(plan.getWithdraw());
			for (ChestPlan.Line line : ChestPlan.parse(lines))
			{
				if (line.everything || line.everythingElse)
				{
					continue;
				}
				String key = iconKey(line);
				Integer known = lineIcons.get(key);
				String knownName = known == null ? null : itemNames.get(known);
				if (known != null && (knownName == null || ChestProgress.dose(knownName) < 0 || ChestProgress.dose(knownName) >= 4))
				{
					continue;
				}
				int best = known == null ? -1 : known;
				int bestDose = knownName == null ? -2 : ChestProgress.dose(knownName);
				// a line of choices shows its first item, or failing that whichever of them has been seen
				for (ChestPlan.Line shown : line.options.isEmpty() ? Collections.singletonList(line) : Arrays.asList(line.options.get(0).get(0), line))
				{
					for (Map.Entry<Integer, String> e : itemNames.entrySet())
					{
						int dose = ChestProgress.dose(e.getValue());
						if (shown.matches(e.getValue()) && (dose > bestDose || (dose == bestDose && e.getKey() < best)))
						{
							best = e.getKey();
							bestDose = dose;
						}
					}
					if (best > 0)
					{
						break;
					}
				}
				if (best > 0 && (known == null || best != known))
				{
					lineIcons.put(key, best);
					changed = true;
				}
			}
		}
		if (changed)
		{
			configManager.setConfiguration(CoxStoragePlannerConfig.GROUP, CoxStoragePlannerConfig.KEY_ICONS, gson.toJson(lineIcons));
		}
	}

	/** What a line's icon is filed under: its item part in lower case, so "Xeric's aid, 2" and "wear Xeric's aid" share one. */
	static String iconKey(ChestPlan.Line line)
	{
		return line.name.toLowerCase(Locale.ROOT);
	}

	private PanelState snapshot()
	{
		PanelState state = new PanelState();
		state.inParty = party.isInParty();
		state.countShared = config.countShared();
		state.countSplit = config.countSplit();
		state.units = config.needUnits();
		state.chests = book().copy(gson);
		learnLineIcons(state.chests);
		state.lineIcons = new HashMap<>(lineIcons);
		state.suppliesTracker = config.suppliesTracker();
		state.currentChest = currentChest;
		state.marking = marking;
		state.putBack = config.chestPutBack();
		state.openChest = openChest != null || currentChest == null ? openChest : progressFor(currentChest);
		state.storageOpen = openStorage != 0;
		state.privateStorageOpen = openStorage == InterfaceID.RAIDS_STORAGE_PRIVATE;
		state.separateSoloNeeds = config.separateSoloNeeds();
		state.separateSoloChests = separateChests();
		state.solo = solo();
		state.inRaid = inRaid;
		Needs needs = needsFor(state.solo);
		for (Potion potion : Potion.values())
		{
			state.need.put(potion, potion.isSupply() ? needs.get(potion) : 0);
		}

		PartyMember local = party.getLocalMember();
		List<PartyMember> partyMembers = state.inParty ? party.getMembers() : Collections.emptyList();

		synchronized (lock)
		{
			state.carriedItems = inventoryItems;
			state.wornItems = wornItems;
			state.inventory = inventory;
			state.privateStorage = privateStorage;
			state.sharedStorage = sharedStorage;
			MemberSupplies mine = new MemberSupplies(inventory, privateStorage, sharedStorage);
			for (PartyMember member : partyMembers)
			{
				PanelState.Member view = new PanelState.Member();
				view.name = name(member);
				view.self = local != null && local.getMemberId() == member.getMemberId();
				view.status = view.self ? mine : members.get(member.getMemberId());
				state.team.add(view);
			}
		}
		return state;
	}
}

package com.coxstorageplanner;

/** What one party member last told us they hold. */
public final class MemberSupplies
{
	/** inventory only */
	private final Supplies carried;
	/** null until they open their private storage */
	private final Supplies stored;
	/** null until someone opens the shared storage */
	private final Supplies shared;

	public MemberSupplies(Supplies carried, Supplies stored, Supplies shared)
	{
		this.carried = carried;
		this.stored = stored;
		this.shared = shared;
	}

	public static MemberSupplies from(CoxStorageMessage message)
	{
		return new MemberSupplies(Supplies.fromWire(message.getCarried()),
			message.getStored() == null ? null : Supplies.fromWire(message.getStored()),
			message.getShared() == null ? null : Supplies.fromWire(message.getShared()));
	}

	public Supplies getCarried()
	{
		return carried;
	}

	public Supplies getStored()
	{
		return stored;
	}

	public Supplies getShared()
	{
		return shared;
	}

	/** Inventory plus private storage as far as it is known. */
	public Supplies getHeld()
	{
		return stored == null ? carried : carried.plus(stored);
	}
}

package com.coxstorageplanner;

/** How dose counts are shown and typed in the sidebar. Everything is stored as doses. */
public enum NeedUnits
{
	DOSES("Doses", "doses"),
	POTIONS("Potions", "potions");

	private final String displayName;
	private final String word;

	NeedUnits(String displayName, String word)
	{
		this.displayName = displayName;
		this.word = word;
	}

	/** The unit word after a number. */
	public String getWord()
	{
		return word;
	}

	/** A dose count in these units: 9 doses is "9" or "2.25". */
	public String format(int doses)
	{
		if (this == DOSES || doses % Potion.DOSES_PER_POTION == 0)
		{
			return String.valueOf(doses / (this == DOSES ? 1 : Potion.DOSES_PER_POTION));
		}
		String text = String.valueOf(doses / (double) Potion.DOSES_PER_POTION);
		return text.endsWith(".0") ? text.substring(0, text.length() - 2) : text;
	}

	/** Doses for something typed in these units, 0 for anything that isn't a number. */
	public int parse(String text)
	{
		try
		{
			double value = Double.parseDouble(text.trim());
			return (int) Math.round(this == DOSES ? value : value * Potion.DOSES_PER_POTION);
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.coxstorageplanner;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;

/**
 * Doses you want to have when you get to Olm, per potion. Stored as "POTION:doses,...".
 * Nothing set at all is stored as "none" so it isn't mistaken for "never set".
 */
public final class Needs
{
	public static final int MAX_DOSES = 99;
	private static final String NONE = "none";

	private final Map<Potion, Integer> doses = new EnumMap<>(Potion.class);

	/** A first plan for a team. */
	public static Needs defaults()
	{
		Needs needs = new Needs();
		needs.set(Potion.OVERLOAD, 4);
		needs.set(Potion.XERICS_AID, 24);
		needs.set(Potion.REVITALISATION, 12);
		needs.set(Potion.PRAYER_ENHANCE, 4);
		return needs;
	}

	/** A first plan for a solo: more running, so another revitalisation. */
	public static Needs soloDefaults()
	{
		Needs needs = defaults();
		needs.set(Potion.REVITALISATION, 16);
		return needs;
	}

	/** The given defaults for something never stored, otherwise whatever parses. */
	public static Needs parse(String encoded, Needs defaults)
	{
		if (encoded == null || encoded.isEmpty())
		{
			return defaults;
		}
		Needs needs = new Needs();
		for (String entry : encoded.split(","))
		{
			String[] parts = entry.split(":");
			try
			{
				if (parts.length == 2)
				{
					needs.set(Potion.valueOf(parts[0]), Integer.parseInt(parts[1]));
				}
				else if (parts.length == 3)
				{
					// the per-room form of 1.0.0: add the rooms up
					Potion potion = Potion.valueOf(parts[1]);
					needs.set(potion, needs.get(potion) + Integer.parseInt(parts[2]));
				}
			}
			catch (IllegalArgumentException e)
			{
				// an entry from another version
			}
		}
		return needs;
	}

	public synchronized String encode()
	{
		List<String> entries = new ArrayList<>();
		for (Map.Entry<Potion, Integer> e : doses.entrySet())
		{
			if (e.getValue() > 0)
			{
				entries.add(e.getKey().name() + ":" + e.getValue());
			}
		}
		return entries.isEmpty() ? NONE : String.join(",", entries);
	}

	public synchronized Needs copy()
	{
		return parse(encode(), new Needs());
	}

	public synchronized int get(Potion potion)
	{
		return doses.getOrDefault(potion, 0);
	}

	/** @return whether anything changed */
	public synchronized boolean set(Potion potion, int count)
	{
		count = Math.max(0, Math.min(MAX_DOSES, count));
		if (get(potion) == count)
		{
			return false;
		}
		doses.put(potion, count);
		return true;
	}
}

package com.coxstorageplanner;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** A snapshot of everything the sidebar shows, built by the plugin and drawn on the Swing thread. */
final class PanelState
{
	static final class Member
	{
		String name;
		boolean self;
		/** null until the member's plugin has sent something */
		MemberSupplies status;
	}

	boolean inParty;
	boolean countShared;
	boolean countSplit;

	Supplies inventory = Supplies.EMPTY;
	/** null until the storage has been opened this raid */
	Supplies privateStorage;
	Supplies sharedStorage;
	final Map<Potion, Integer> need = new EnumMap<>(Potion.class);
	/** Whether the numbers are for a solo raid: the raid's size while in one, the tab otherwise. */
	boolean solo;
	/** Whether the player is in a raid, when the Team | Solo switch overrides the party size instead of being saved. */
	boolean inRaid;
	boolean separateSoloNeeds;
	/** Whether solo raids have their own chest plans, so {@link #chests} is the set for {@link #solo}. */
	boolean separateSoloChests;
	/** Whether the Supplies part of the sidebar is on. */
	boolean suppliesTracker;
	NeedUnits units = NeedUnits.POTIONS;
	ChestBook chests = new ChestBook();
	/** Chest of the room the player is in, null outside one. */
	String currentChest;
	/** Item name to quantity in the inventory, for the steps of a chest that isn't open. */
	Map<String, Integer> carriedItems = new LinkedHashMap<>();
	/** Item name to quantity worn, which counts as withdrawn. */
	Map<String, Integer> wornItems = new LinkedHashMap<>();
	/** Progress at the storage that's open right now, or at the room's while it's shut; null when there's neither. */
	ChestProgress openChest;
	/** Whether a storage's interface is open, and whether it's the private one. */
	boolean storageOpen;
	boolean privateStorageOpen;
	/** Item ids seen for the lines of the chest lists, by the line's text in lower case, for the sidebar's icons. */
	Map<String, Integer> lineIcons = new LinkedHashMap<>();
	/** Whether clicking items in a storage or the inventory adds them to the chest's lists. */
	boolean marking;
	/** Whether an ordered plan wants carried items of later steps put back first. */
	boolean putBack;

	final List<Member> team = new ArrayList<>();

	/** Everything within reach: inventory, private storage, and shared storage if that counts. */
	private Supplies held()
	{
		Supplies held = inventory;
		if (privateStorage != null)
		{
			held = held.plus(privateStorage);
		}
		Supplies shared = shared();
		if (countShared && shared != null)
		{
			held = held.plus(shared);
		}
		return held;
	}

	/** The shared storage as you saw it, or as a party member did if you haven't opened it. */
	Supplies shared()
	{
		if (sharedStorage != null)
		{
			return sharedStorage;
		}
		for (Member member : team)
		{
			if (member.status != null && member.status.getShared() != null)
			{
				return member.status.getShared();
			}
		}
		return null;
	}

	/** Overload doses you hold as sets of elder, twisted and kodai. */
	int splitHeld()
	{
		return held().splitOverloadDoses();
	}

	/** Doses that count towards what you need. */
	int have(Potion potion)
	{
		int have = held().doses(potion);
		if (potion == Potion.OVERLOAD && countSplit)
		{
			have += splitHeld();
		}
		return have;
	}

	int shortfall(Potion potion)
	{
		return Math.max(0, need.getOrDefault(potion, 0) - have(potion));
	}
}

package com.coxstorageplanner;

/**
 * The raid potions. Every raid potion has 12 consecutive item ids:
 * (-) 1-4 dose, regular 1-4 dose, (+) 1-4 dose.
 * The supply potions get a row in the sidebar totals. Elder, twisted and kodai are only counted
 * as the three parts of a split overload, which is what Vanguards drop one set of.
 */
public enum Potion
{
	OVERLOAD("Overload", "Ovl", Ids.raid(20985), true, true),
	XERICS_AID("Xeric's aid", "Aid", Ids.raid(20973), true, true),
	REVITALISATION("Revitalisation", "Revit", Ids.raid(20949), true, true),
	PRAYER_ENHANCE("Prayer enhance", "Enh", Ids.raid(20961), true, true),
	ELDER("Elder", "Elder", Ids.raid(20913), false, false),
	TWISTED("Twisted", "Twisted", Ids.raid(20925), false, false),
	KODAI("Kodai", "Kodai", Ids.raid(20937), false, false),
	/** One elder, one twisted and one kodai, claimed together. Not an item of its own. */
	SPLIT_OVERLOAD("Split overload", "Split", new int[0], false, true);

	public static final int DOSES_PER_POTION = 4;

	private static final class Ids
	{
		/** The 12 ids of a raid potion, starting at the (-) 1 dose. */
		private static int[] raid(int first)
		{
			int[] ids = new int[3 * DOSES_PER_POTION];
			for (int i = 0; i < ids.length; i++)
			{
				ids[i] = first + i;
			}
			return ids;
		}
	}

	private final String displayName;
	private final String shortName;
	/** Item ids, the one at index i holding i % 4 + 1 doses. */
	private final int[] itemIds;
	private final boolean supply;
	private final boolean claimable;

	Potion(String displayName, String shortName, int[] itemIds, boolean supply, boolean claimable)
	{
		this.displayName = displayName;
		this.shortName = shortName;
		this.itemIds = itemIds;
		this.supply = supply;
		this.claimable = claimable;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public String getShortName()
	{
		return shortName;
	}

	/** Whether the sidebar totals and the "needed" settings cover this potion. */
	public boolean isSupply()
	{
		return supply;
	}

	/** Whether rooms drop it as something to claim. */
	public boolean isClaimable()
	{
		return claimable;
	}

	/** Item id of the full potion, used for the sidebar icon. */
	public int getIconItemId()
	{
		return itemIds.length == 0 ? -1 : itemIds[itemIds.length - 1];
	}

	public boolean matches(int itemId)
	{
		return doses(itemId) > 0;
	}

	/** Doses in one item with this id, 0 if it isn't this potion. */
	public int doses(int itemId)
	{
		for (int i = 0; i < itemIds.length; i++)
		{
			if (itemIds[i] == itemId)
			{
				return i % DOSES_PER_POTION + 1;
			}
		}
		return 0;
	}

	public static Potion of(int itemId)
	{
		for (Potion potion : values())
		{
			if (potion.matches(itemId))
			{
				return potion;
			}
		}
		return null;
	}
}

package com.coxstorageplanner;

import java.util.Arrays;

/** Doses per potion for one place (inventory, private storage, shared storage). */
public final class Supplies
{
	public static final Supplies EMPTY = new Supplies(new int[Potion.values().length]);

	private final int[] doses;

	private Supplies(int[] doses)
	{
		this.doses = doses;
	}

	/** @param doses doses per potion, in {@link Potion} order; missing entries count as 0 */
	public static Supplies of(int[] doses)
	{
		int[] copy = new int[Potion.values().length];
		if (doses != null)
		{
			for (int i = 0; i < copy.length && i < doses.length; i++)
			{
				copy[i] = Math.max(0, doses[i]);
			}
		}
		return new Supplies(copy);
	}

	/** Counts the doses in a container given as parallel item id / quantity arrays. */
	public static Supplies count(int[] itemIds, int[] quantities)
	{
		int[] doses = new int[Potion.values().length];
		for (int i = 0; i < itemIds.length; i++)
		{
			Potion potion = Potion.of(itemIds[i]);
			if (potion != null)
			{
				doses[potion.ordinal()] += potion.doses(itemIds[i]) * Math.max(1, quantities[i]);
			}
		}
		return new Supplies(doses);
	}

	public int doses(Potion potion)
	{
		return doses[potion.ordinal()];
	}

	/** Doses of elder, twisted and kodai that can be drunk as a set, which is what an overload dose is. */
	public int splitOverloadDoses()
	{
		return Math.min(doses(Potion.ELDER), Math.min(doses(Potion.TWISTED), doses(Potion.KODAI)));
	}

	public Supplies plus(Supplies other)
	{
		int[] sum = new int[doses.length];
		for (int i = 0; i < sum.length; i++)
		{
			sum[i] = doses[i] + other.doses[i];
		}
		return new Supplies(sum);
	}

	public int[] toArray()
	{
		return doses.clone();
	}

	/** Where 1.0.0 had a potion that's gone since; party messages keep the gap so both versions read each other. */
	private static final int WIRE_GAP = 4;

	/** The doses as party messages carry them. */
	public int[] toWire()
	{
		int[] wire = new int[doses.length + 1];
		for (int i = 0; i < doses.length; i++)
		{
			wire[i < WIRE_GAP ? i : i + 1] = doses[i];
		}
		return wire;
	}

	/** @param wire doses from a party message; missing entries count as 0 */
	public static Supplies fromWire(int[] wire)
	{
		int[] doses = new int[Potion.values().length];
		if (wire != null)
		{
			for (int i = 0; i < doses.length; i++)
			{
				int at = i < WIRE_GAP ? i : i + 1;
				doses[i] = at < wire.length ? Math.max(0, wire[at]) : 0;
			}
		}
		return new Supplies(doses);
	}

	@Override
	public boolean equals(Object o)
	{
		return o instanceof Supplies && Arrays.equals(doses, ((Supplies) o).doses);
	}

	@Override
	public int hashCode()
	{
		return Arrays.hashCode(doses);
	}

	@Override
	public String toString()
	{
		return Arrays.toString(doses);
	}
}

package com.coxstorageplanner;

import java.awt.Color;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class ChestGlowBlendTest
{
	@Test
	public void greenToRedGoesByYellowAndOrange()
	{
		Color green = new Color(30, 220, 60, 255);
		Color red = new Color(240, 40, 40, 255);
		float[] second = hsb(ChestItemOverlay.blend(green, red, ChestItemOverlay.step(1, 4)));
		float[] third = hsb(ChestItemOverlay.blend(green, red, ChestItemOverlay.step(2, 4)));
		// hue in degrees: green 120-ish, yellow 60, orange 30, red 0
		assertTrue(second[0] * 360 > 55 && second[0] * 360 < 70);
		assertTrue(third[0] * 360 > 25 && third[0] * 360 < 40);
		assertEquals(0f, ChestItemOverlay.step(0, 4), 0f);
		assertEquals(1f, ChestItemOverlay.step(3, 4), 0f);
		// two left: green and yellow, not green and red
		assertEquals(0.5f, ChestItemOverlay.step(1, 4), 0f);
		assertEquals(1f, ChestItemOverlay.step(1, 2), 0f);
		assertEquals(green, ChestItemOverlay.blend(green, red, 0));
		assertEquals(red, ChestItemOverlay.blend(green, red, 1));
		// no brown in between
		Color mid = ChestItemOverlay.blend(green, red, 0.5f);
		assertTrue(hsb(mid)[2] > 0.8);
	}

	@Test
	public void greyIsMetInAStraightLine()
	{
		Color grey = new Color(128, 128, 128, 100);
		Color red = new Color(240, 40, 40, 255);
		Color mid = ChestItemOverlay.blend(red, grey, 0.5f);
		assertEquals(184, mid.getRed());
		assertEquals(178, mid.getAlpha());
	}

	private static float[] hsb(Color c)
	{
		return Color.RGBtoHSB(c.getRed(), c.getGreen(), c.getBlue(), null);
	}
}

package com.coxstorageplanner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

public class ChestLayoutTest
{
	private static final int SLOTS = 28;

	/** An inventory and a storage to click through: a withdrawal lands in the first empty slot, a deposit leaves a hole. */
	private static final class Game
	{
		final ChestPlan plan;
		final String[] slots = new String[SLOTS];
		final int[] quantities = new int[SLOTS];
		final Map<String, Integer> storage = new LinkedHashMap<>();
		final Set<String> stackable;
		final int capacity;
		boolean withdrawing;
		boolean loose;
		boolean[] numbered;
		int deposits;
		int withdrawals;
		int drags;
		int mixes;
		/** How often the plan went from putting in to taking out. */
		int rounds;

		Game(ChestPlan plan, int capacity, Set<String> stackable, String... carried)
		{
			this.plan = plan;
			this.capacity = capacity;
			this.stackable = stackable;
			for (int i = 0; i < carried.length; i++)
			{
				slots[i] = carried[i];
				quantities[i] = carried[i] == null ? 0 : 1;
			}
		}

		Game store(String name, int quantity)
		{
			storage.merge(name, quantity, Integer::sum);
			return this;
		}

		Map<String, Integer> inventory()
		{
			Map<String, Integer> items = new LinkedHashMap<>();
			for (int i = 0; i < SLOTS; i++)
			{
				if (slots[i] != null)
				{
					items.merge(slots[i], quantities[i], Integer::sum);
				}
			}
			return items;
		}

		/** Storage slots taken: one per item, one per stack of a stackable one. */
		int used()
		{
			int used = 0;
			for (Map.Entry<String, Integer> e : storage.entrySet())
			{
				used += stackable.contains(e.getKey()) ? 1 : e.getValue();
			}
			return used;
		}

		ChestProgress progress()
		{
			Map<String, Integer> inventory = inventory();
			ChestProgress progress = new ChestProgress(plan, inventory, Collections.emptyMap(), inventory, new HashMap<>(storage),
				true, stackable, new ChestProgress.Carried(slots.clone(), quantities.clone(), capacity < 0 ? -1 : capacity - used(), withdrawing, loose, numbered));
			withdrawing = progress.withdrawing;
			loose = progress.loose();
			numbered = progress.numbered();
			return progress;
		}

		void deposit(int slot)
		{
			assertTrue("storage has room for " + slots[slot],
				capacity < 0 || (stackable.contains(slots[slot]) && storage.containsKey(slots[slot])) || used() < capacity);
			storage.merge(slots[slot], quantities[slot], Integer::sum);
			slots[slot] = null;
			quantities[slot] = 0;
			deposits++;
		}

		void withdraw(String name, int quantity)
		{
			int left = storage.get(name) - quantity;
			if (left > 0)
			{
				storage.put(name, left);
			}
			else
			{
				storage.remove(name);
			}
			withdrawals++;
			for (int i = 0; i < SLOTS; i++)
			{
				if (stackable.contains(name) && name.equals(slots[i]))
				{
					quantities[i] += quantity;
					return;
				}
			}
			for (int i = 0; i < SLOTS; i++)
			{
				if (slots[i] == null)
				{
					slots[i] = name;
					quantities[i] = quantity;
					return;
				}
			}
			throw new AssertionError("inventory full");
		}

		/** Does what lights up, one click at a time, until the plan is done or stuck. @return the last progress */
		ChestProgress play()
		{
			ChestProgress.Phase last = null;
			for (int click = 0; click < 400; click++)
			{
				ChestProgress progress = progress();
				if (progress.isDone() || progress.blocked)
				{
					return progress;
				}
				if (progress.phase() == ChestProgress.Phase.MIX)
				{
					last = progress.phase();
					ChestProgress.Mix mix = progress.mix();
					int from = progress.moveFrom();
					int to = progress.moveTo();
					assertEquals(slots[from], mix.from);
					assertEquals(slots[to], mix.to);
					assertEquals(slots[from], progress.moveName());
					int doses = ChestProgress.dose(slots[from]) + ChestProgress.dose(slots[to]);
					slots[to] = slots[to].substring(0, slots[to].length() - 2) + Math.min(4, doses) + ")";
					slots[from] = doses > 4 ? slots[from].substring(0, slots[from].length() - 2) + (doses - 4) + ")" : null;
					quantities[from] = doses > 4 ? 1 : 0;
					mixes++;
					continue;
				}
				if (progress.phase() == ChestProgress.Phase.MOVE)
				{
					last = progress.phase();
					int from = progress.moveFrom();
					int to = progress.moveTo();
					assertEquals(slots[from], progress.moveName());
					String name = slots[to];
					int quantity = quantities[to];
					slots[to] = slots[from];
					quantities[to] = quantities[from];
					slots[from] = name;
					quantities[from] = quantity;
					drags++;
					continue;
				}
				if (progress.phase() == ChestProgress.Phase.WITHDRAW && last == ChestProgress.Phase.DEPOSIT)
				{
					rounds++;
				}
				last = progress.phase();
				if (progress.phase() == ChestProgress.Phase.DEPOSIT)
				{
					int slot = -1;
					for (int i = 0; i < SLOTS && slot < 0; i++)
					{
						if (slots[i] != null && progress.depositsSlot(i, slots[i]))
						{
							slot = i;
						}
					}
					assertTrue("something to put in", slot >= 0);
					deposit(slot);
				}
				else
				{
					ChestProgress.Click next = progress.queue().get(0);
					String pick = null;
					for (String name : storage.keySet())
					{
						if (next.step.line.matches(name) && progress.fullest(next.step.line, name))
						{
							pick = name;
						}
					}
					assertTrue("the next click is in the storage", pick != null);
					assertTrue(progress.wantsNext(pick));
					withdraw(pick, next.step.stack ? next.step.remaining : 1);
				}
			}
			throw new AssertionError("never finished");
		}

		List<String> carried()
		{
			List<String> names = new ArrayList<>(Arrays.asList(slots));
			while (!names.isEmpty() && names.get(names.size() - 1) == null)
			{
				names.remove(names.size() - 1);
			}
			return names;
		}
	}

	@Test
	public void whatLandsInTheWrongSlotGoesBackInBeforeTheNextWithdrawal()
	{
		ChestPlan plan = plan("everything else", "Twisted bow", "Dragon claws", "Revitalisation, 2", "Overload", "Book of the dead", "Rune pouch");
		Game game = new Game(plan, 25, Collections.emptySet()).store("Twisted bow", 1).store("Dragon claws", 1).store("Revitalisation(4)", 2)
			.store("Overload (+)(4)", 1).store("Book of the dead", 1).store("Rune pouch", 1);
		assertEquals(ChestProgress.Phase.WITHDRAW, game.progress().phase());
		game.withdraw("Twisted bow", 1);
		assertEquals(ChestProgress.Phase.WITHDRAW, game.progress().phase());
		// the book clicked far too early lands in the claws' slot: with room in the storage it goes back in right away
		game.withdraw("Book of the dead", 1);
		ChestProgress progress = game.progress();
		assertEquals(ChestProgress.Phase.DEPOSIT, progress.phase());
		assertEquals(Arrays.asList("Book of the dead"), progress.outOfOrder);
		assertTrue(progress.redepositsNow("Book of the dead"));
		assertTrue(progress.depositsSlot(1, "Book of the dead"));
		assertFalse(progress.depositsSlot(0, "Twisted bow"));
		assertTrue(progress.queue().isEmpty());
		assertTrue(game.play().isDone());
		assertEquals(Arrays.asList("Twisted bow", "Dragon claws", "Revitalisation(4)", "Revitalisation(4)", "Overload (+)(4)",
			"Book of the dead", "Rune pouch"), game.carried());
		assertEquals(1, game.deposits);
		assertEquals(0, game.drags);
	}

	@Test
	public void aLineOfChoicesTakesTheSlotsOfTheOneChosen()
	{
		ChestPlan plan = plan("everything else", "Twisted bow", "Venator bow | *chinchompa & Twisted buckler", "Overload");
		Set<String> stacks = Collections.singleton("Black chinchompa");
		// the venator bow is in the storage: one slot for it, and the buckler carried goes in
		Game game = new Game(plan, 25, stacks, "Twisted buckler").store("Twisted bow", 1).store("Venator bow", 1)
			.store("Black chinchompa", 400).store("Overload (+)(4)", 1);
		ChestProgress progress = game.play();
		assertTrue(progress.isDone());
		assertEquals(Arrays.asList("Twisted bow", "Venator bow", "Overload (+)(4)"), game.carried());
		assertEquals(Integer.valueOf(1), game.storage.get("Twisted buckler"));

		// no venator bow: the chinchompas and the buckler, a slot each
		game = new Game(plan, 25, stacks, "Twisted buckler").store("Twisted bow", 1)
			.store("Black chinchompa", 400).store("Overload (+)(4)", 1);
		progress = game.play();
		assertTrue(progress.isDone());
		assertEquals(Arrays.asList("Twisted bow", "Black chinchompa", "Twisted buckler", "Overload (+)(4)"), game.carried());
	}

	@Test
	public void aClickKeepsItsNumber()
	{
		ChestPlan plan = plan("everything else", "Twisted bow", "Dragon claws", "Xeric's aid, 3", "Overload", "Lockpick", "Book of the dead");
		Game game = new Game(plan, 25, Collections.emptySet(), "Twisted bow", "Dragon claws", "Xeric's aid(4)", null, null, "Overload (+)(4)")
			.store("Xeric's aid(4)", 4).store("Book of the dead", 1);
		// clicks 4, 5 and 7 of the list are the ones to make: they read 1, 2 and 3
		ChestProgress progress = game.progress();
		assertEquals(3, progress.toClick());
		assertEquals(1, progress.number(progress.queue().get(0).number));
		assertEquals(2, progress.number(progress.queue().get(1).number));
		assertEquals(3, progress.number(progress.queue().get(2).number));
		assertEquals(1, progress.number(progress.withdrawals.get(2)));
		assertEquals(3, progress.number(progress.withdrawals.get(5)));

		// the first one made, the other two are still 2 and 3
		game.withdraw("Xeric's aid(4)", 1);
		progress = game.progress();
		assertEquals(2, progress.toClick());
		assertEquals(0, progress.queue().get(0).step.rank);
		assertEquals(2, progress.number(progress.queue().get(0).number));
		assertEquals(3, progress.number(progress.queue().get(1).number));
		assertEquals(2, progress.number(progress.withdrawals.get(2)));

		// the storage opened again counts from the next click
		game.numbered = null;
		progress = game.progress();
		assertEquals(1, progress.number(progress.queue().get(0).number));
		assertEquals(2, progress.number(progress.queue().get(1).number));

		// the same going by counts
		Map<String, Integer> inventory = new LinkedHashMap<>();
		inventory.put("Twisted bow", 1);
		inventory.put("Xeric's aid(4)", 1);
		Map<String, Integer> storage = new HashMap<>();
		storage.put("Dragon claws", 1);
		storage.put("Xeric's aid(4)", 2);
		storage.put("Book of the dead", 1);
		ChestProgress.Carried carried = new ChestProgress.Carried(new String[SLOTS], new int[SLOTS], -1, false);
		ChestProgress counts = new ChestProgress(plan, inventory, Collections.emptyMap(), inventory, storage, false, Collections.emptySet(), carried);
		assertEquals(4, counts.toClick());
		assertEquals(1, counts.number(counts.withdrawals.get(1)));
		assertEquals(2, counts.number(counts.withdrawals.get(2)));
		assertEquals(4, counts.number(counts.withdrawals.get(5)));
		inventory.put("Dragon claws", 1);
		storage.remove("Dragon claws");
		counts = new ChestProgress(plan, inventory, Collections.emptyMap(), inventory, storage, false, Collections.emptySet(),
			carried.with(-1, false, false, counts.numbered()));
		assertEquals(3, counts.toClick());
		assertEquals(2, counts.number(counts.withdrawals.get(2)));
		assertEquals(4, counts.number(counts.withdrawals.get(5)));

		// a click the numbers left out undone since: they start over rather than run past the list
		inventory.remove("Twisted bow");
		storage.put("Twisted bow", 1);
		counts = new ChestProgress(plan, inventory, Collections.emptyMap(), inventory, storage, false, Collections.emptySet(),
			carried.with(-1, false, false, counts.numbered()));
		assertEquals(1, counts.number(counts.withdrawals.get(0)));
		assertEquals(2, counts.number(counts.withdrawals.get(2)));
	}

	@Test
	public void theClicksLeftCountFromOne()
	{
		ChestPlan plan = plan("everything else", "Twisted bow", "Dragon claws", "Xeric's aid, 3", "Overload", "Lockpick", "Book of the dead");
		// the bow, the claws and one aid are in place; the overload is carried too, right where it goes
		Game game = new Game(plan, 25, Collections.emptySet(), "Twisted bow", "Dragon claws", "Xeric's aid(4)", null, null, "Overload (+)(4)")
			.store("Xeric's aid(4)", 4).store("Book of the dead", 1);
		ChestProgress progress = game.progress();
		assertEquals(ChestProgress.Phase.WITHDRAW, progress.phase());
		assertTrue(progress.withdrawals.get(0).done);
		// two aids are the next two clicks, 1 and 2, and the book past the overload is 3: no gap for what's done
		ChestProgress.Step aids = progress.withdrawals.get(2);
		assertEquals(0, aids.rank);
		assertEquals(2, aids.now);
		assertTrue(progress.withdrawals.get(3).done);
		assertEquals(0, progress.withdrawals.get(3).now);
		assertTrue(progress.withdrawals.get(4).missing);
		assertEquals(0, progress.withdrawals.get(4).now);
		ChestProgress.Step book = progress.withdrawals.get(5);
		assertEquals(2, book.rank);
		assertEquals(1, book.now);
		// in the whole list those are clicks 4, 5 and 7, which the colour goes by
		assertEquals(4, progress.queue().get(0).number);
		assertEquals(7, progress.queue().get(2).number);
		ChestItemOverlay overlay = new ChestItemOverlay(null, null, null, null);
		ChestItemOverlay.Click click = overlay.withdrawal(progress, "Xeric's aid(4)", 4, 4);
		assertEquals(0, click.rank);
		assertEquals(2, click.count);
		assertEquals(2, overlay.withdrawal(progress, "Book of the dead", 1, 4).rank);

		// the same going by counts
		Map<String, Integer> inventory = game.inventory();
		ChestProgress counts = new ChestProgress(plan, inventory, Collections.emptyMap(), inventory, new HashMap<>(game.storage), false, Collections.emptySet());
		assertEquals(0, counts.withdrawals.get(2).rank);
		assertEquals(2, counts.withdrawals.get(2).now);
		assertEquals(0, counts.withdrawals.get(3).now);
		assertEquals(2, counts.withdrawals.get(5).rank);
		assertEquals(1, counts.withdrawals.get(5).now);
	}

	@Test
	public void aDragThatWaitsIsListedAsADrag()
	{
		ChestPlan plan = plan("everything else", "Gear a", "Gear b", "Gear c", "Gear d", "Gear e");
		// one slot free; e sits where c goes, and a round of withdrawals is on
		Game game = new Game(plan, 5, Collections.emptySet(), "Junk a", "Junk b", "Gear e")
			.store("Gear a", 1).store("Gear b", 1).store("Gear c", 1).store("Gear d", 1);
		game.withdrawing = true;
		ChestProgress progress = game.progress();
		assertEquals(1, progress.free);
		assertEquals(ChestProgress.Phase.WITHDRAW, progress.phase());
		assertFalse(progress.loose());
		assertEquals(1, progress.queue().size());
		assertTrue(progress.queue().get(0).step.line.matches("Gear d"));
		// the drag isn't up yet, and it isn't called a redeposit meanwhile
		assertTrue(progress.moves().isEmpty());
		assertEquals(1, progress.drags().size());
		assertEquals(2, progress.drags().get(0)[0]);
		assertEquals(4, progress.drags().get(0)[1]);
		assertTrue(progress.outOfOrder.isEmpty());

		// d is out, nothing else comes out in place: the drag, not a, b and c into whatever slots are empty
		game.withdraw("Gear d", 1);
		progress = game.progress();
		assertEquals(ChestProgress.Phase.MOVE, progress.phase());
		assertEquals("Gear e", progress.moveName());
		assertTrue(game.play().isDone());
		assertEquals(Arrays.asList("Gear a", "Gear b", "Gear c", "Gear d", "Gear e"), game.carried());
		assertEquals(1, game.drags);
		assertEquals(2, game.deposits);
	}

	private static ChestPlan plan(String putIn, String... takeOut)
	{
		ChestPlan plan = new ChestPlan("RAIDS_END#1", "Pre-Vanguards");
		if (putIn != null)
		{
			plan.getDeposit().add(putIn);
		}
		plan.getWithdraw().addAll(Arrays.asList(takeOut));
		plan.setOrdered(true);
		return plan;
	}

	@Test
	public void gearCarriedInTheWrongSlotGoesBackIn()
	{
		// the three were never put in, so they sit where the list's first items belong
		ChestPlan plan = plan("everything else", "Twisted bow", "Dragon claws", "Avernic defender", "Emberlight", "Elder maul", "Xeric's aid, 2");
		Game game = new Game(plan, 25, Collections.emptySet(), "Avernic defender", "Emberlight", "Elder maul", "Shark")
