		Game game = new Game(plan, 8, Collections.emptySet());
		for (int i = 0; i < 8; i++)
		{
			wanted[i] = "Gear " + (char) ('a' + i);
			plan.getWithdraw().add(wanted[i]);
			game.slots[i] = "Junk " + (char) ('a' + i);
			game.quantities[i] = 1;
			game.store(wanted[i], 1);
		}
