		storage.remove("Twisted buckler");
		progress = new ChestProgress(plan, none, none, none, storage);
		assertEquals(4, progress.withdrawals.size());
		assertTrue(progress.withdrawals.get(2).missing);
		// a storage not seen yet: the first choice
		progress = new ChestProgress(plan, none, none, none, null);
		assertEquals(3, progress.withdrawals.size());
		assertEquals("Venator bow", progress.withdrawals.get(1).line.text);
	}

	@Test
	public void choicesKeepTheirCountsAndTheirWear()
	{
		// with an "&" each item has a count of its own
		ChestPlan.Line line = ChestPlan.parse(Arrays.asList("Venator bow | Black chinchompa, 500 & Twisted buckler")).get(0);
		assertEquals(1, line.count);
		assertFalse(line.counted);
		assertEquals(500, line.options.get(1).get(0).count);
		assertEquals(1, line.options.get(1).get(1).count);
		assertTrue(line.matches("Black chinchompa"));
		// without one, the count at the end covers every choice
		ChestPlan.Line either = ChestPlan.parse(Arrays.asList("Xeric's aid | Revitalisation, 3")).get(0);
		assertTrue(either.either);
		assertEquals(3, either.count);
		assertEquals(3, either.options.get(0).get(0).count);
		assertEquals(3, either.options.get(1).get(0).count);
		ChestPlan.Line worn = ChestPlan.parse(Arrays.asList("wear Torva full helm | Neitiznot faceguard & Amulet of fury")).get(0);
		assertTrue(worn.wear);
		assertTrue(worn.options.get(1).get(1).wear);
		assertEquals("Amulet of fury", worn.options.get(1).get(1).name);

		ChestPlan plan = new ChestPlan("RAIDS_END#1", "Pre-Vanguards");
		plan.getWithdraw().add("Xeric's aid | Revitalisation, 3");
		Map<String, Integer> none = Collections.emptyMap();
		// three aids there: only the aids, though the revitalisations are there too
		ChestProgress progress = new ChestProgress(plan, none, none, none, ChestProgress.tally(Arrays.asList("Xeric's aid(4)",
			"Xeric's aid(4)", "Xeric's aid(4)", "Revitalisation(4)", "Revitalisation(4)", "Revitalisation(4)")));
		assertTrue((progress.highlightsWithdraw("Xeric's aid(4)", 99) != null));
		assertFalse((progress.highlightsWithdraw("Revitalisation(4)", 99) != null));
		// two aids, three revitalisations: the revitalisations
		progress = new ChestProgress(plan, none, none, none, ChestProgress.tally(Arrays.asList("Xeric's aid(4)",
			"Xeric's aid(4)", "Revitalisation(4)", "Revitalisation(4)", "Revitalisation(4)")));
		assertFalse((progress.highlightsWithdraw("Xeric's aid(4)", 99) != null));
		assertTrue((progress.highlightsWithdraw("Revitalisation(4)", 99) != null));
		// neither makes three: any mix of them, as before
		progress = new ChestProgress(plan, none, none, none, ChestProgress.tally(Arrays.asList("Xeric's aid(4)",
			"Xeric's aid(4)", "Revitalisation(4)", "Revitalisation(4)")));
		assertEquals(1, progress.withdrawals.size());
		assertTrue((progress.highlightsWithdraw("Xeric's aid(4)", 99) != null));
		assertTrue((progress.highlightsWithdraw("Revitalisation(4)", 99) != null));
		assertEquals(3, progress.withdrawals.get(0).remaining);
	}

	@Test
	public void wearLinesParse()
	{
		ChestPlan.Line line = ChestPlan.parse(Arrays.asList("wear Scythe of vitur")).get(0);
		assertTrue(line.wear);
		assertEquals("Scythe of vitur", line.name);
		assertTrue(line.matches("Scythe of vitur"));
		ChestPlan.Line counted = ChestPlan.parse(Arrays.asList("Equip Rada's blessing, 2")).get(0);
		assertTrue(counted.wear);
		assertEquals(2, counted.count);
		assertEquals("Rada's blessing", counted.name);
		assertTrue(ChestPlan.parse(Arrays.asList("everything else")).get(0).everythingElse);
		assertFalse(ChestPlan.parse(Arrays.asList("everything")).get(0).everythingElse);
	}

	@Test
	public void carriedItemsOfLaterStepsGoBackFirst()
	{
		ChestPlan plan = new ChestPlan("RAIDS_END#2", "Pre-Olm");
		plan.getWithdraw().addAll(Arrays.asList("Xeric's aid, 2", "Overload", "Prayer enhance"));
		plan.setOrdered(true);
		Map<String, Integer> none = Collections.emptyMap();

		// the enhance is carried before the aid and the overload: back in it goes
		Map<String, Integer> carried = ChestProgress.tally(Arrays.asList("Xeric's aid(4)", "Prayer enhance(4)"));
		ChestProgress progress = new ChestProgress(plan, carried, none, carried, null, true);
		assertEquals(Arrays.asList("Prayer enhance(4)"), progress.outOfOrder);
		assertEquals(ChestProgress.Phase.DEPOSIT, progress.phase());
		assertTrue(progress.highlightsDeposit("Prayer enhance(4)"));
		assertFalse(progress.highlightsDeposit("Xeric's aid(4)"));
		assertNull(progress.highlightsWithdraw("Xeric's aid(4)", 3));

		// with the setting off it's just the plan as written
		ChestProgress loose = new ChestProgress(plan, carried, none, carried, null, false);
		assertTrue(loose.outOfOrder.isEmpty());
		assertEquals(1, loose.highlightsWithdraw("Xeric's aid(4)", 3).order);

		// put back: the next step lights again
		carried = ChestProgress.tally(Arrays.asList("Xeric's aid(4)"));
		progress = new ChestProgress(plan, carried, none, carried, null, true);
		assertTrue(progress.outOfOrder.isEmpty());
		assertEquals(1, progress.highlightsWithdraw("Xeric's aid(4)", 3).order);

		// the item of the next step, or of a done one, is never out of order
		carried = ChestProgress.tally(Arrays.asList("Xeric's aid(4)", "Xeric's aid(4)", "Overload (+)(4)"));
		assertTrue(new ChestProgress(plan, carried, none, carried, null, true).outOfOrder.isEmpty());
	}

	@Test
	public void chestsRoundTripThroughJson()
	{
		ChestBook book = new ChestBook();
		ChestPlan plan = book.getOrCreate("RAIDS_END#2", "Pre-Olm");
		plan.getDeposit().add("everything else");
		plan.getWithdraw().addAll(Arrays.asList("wear Scythe of vitur", "Xeric's aid, 2"));
		plan.setOrdered(true);
		Gson gson = new Gson();
		ChestBook back = ChestBook.parse(book.encode(gson), gson);
		assertEquals(book.encode(gson), back.encode(gson));
		assertTrue(back.get("RAIDS_END#2").isOrdered());
		assertTrue(ChestBook.parse("", gson).all().isEmpty());
		assertTrue(ChestBook.parse("not json", gson).all().isEmpty());
	}

	@Test
	public void overlappingLinesShareWhatIsCarried()
	{
		ChestPlan plan = new ChestPlan("RAIDS_END#1", "Olm");
		plan.getWithdraw().add("Xeric's aid, 2");
		plan.getWithdraw().add("*aid*, 1");
		Map<String, Integer> two = Collections.singletonMap("Xeric's aid(4)", 2);
		Map<String, Integer> stored = Collections.singletonMap("Xeric's aid(4)", 1);
		ChestProgress progress = new ChestProgress(plan, two, Collections.emptyMap(), stored);
		assertTrue(progress.withdrawals.get(0).done);
		assertFalse(progress.withdrawals.get(1).done);
		Map<String, Integer> three = Collections.singletonMap("Xeric's aid(4)", 3);
		assertTrue(new ChestProgress(plan, three, Collections.emptyMap(), stored).withdrawals.get(1).done);
	}
}

